// Quote library — generated by tools/build_quotes.py from quotes.json + audio/q/*.mp3. Do not edit.
window.QUOTES = [
 {"id": "q0001", "vi": "Thở vào biết mình đang thở.\nThở ra mỉm cười.", "vo": ["vi"], "author": "Giận"},
 {"id": "q0002", "vi": "Đơn giản hoá: bớt muốn, bớt mệt.", "vo": ["vi"], "author": "Giận"},
 {"id": "q0003", "vi": "Có mặt trọn vẹn trong việc đang làm.", "vo": ["vi"], "author": "Giận"},
 {"id": "q0004", "vi": "Mỗi bước chân là một nụ hôn lên mặt đất.", "vo": ["vi"], "author": "Giận"},
 {"id": "q0005", "vi": "Hạnh phúc có mặt ngay bây giờ.", "vo": ["vi"], "author": "Giận"},
 {"id": "q0006", "vi": "Khi giận, hãy trở về với hơi thở.\nĐừng nói, đừng làm gì cả.\nThở cho đến khi bình an trở lại.", "vo": ["vi"], "author": "Giận"},
 {"id": "q0007", "vi": "Giận không phải là kẻ thù.\nGiận chỉ là một đứa bé cần được ôm ấp bằng chánh niệm.", "vo": ["vi"], "author": "Giận"},
 {"id": "q0008", "vi": "Khi ta nhận diện được cơn giận,\nta đã bắt đầu tự do khỏi nó.", "vo": ["vi"], "author": "Giận"},
 {"id": "q0009", "vi": "Không ai có thể làm ta khổ nếu trong ta không có sẵn hạt giống khổ.\nKhi giận, hãy nhìn sâu để hiểu.", "vo": ["vi"], "author": "Giận"},
 {"id": "q0010", "vi": "Ôm lấy cơn giận bằng hơi thở chánh niệm,\ngiống như mẹ ôm con thơ vào lòng.", "vo": ["vi"], "author": "Giận"},
 {"id": "q0011", "vi": "Mọi sự trên đời đều có nhân duyên.\nGieo nhân lành sẽ gặt quả lành.", "vo": ["vi"], "author": "Muôn Kiếp Nhân Sinh"},
 {"id": "q0012", "vi": "Con người không chỉ sống một đời.\nMỗi kiếp là một hành trình học hỏi và trả nợ.", "vo": ["vi"], "author": "Muôn Kiếp Nhân Sinh"},
 {"id": "q0013", "vi": "Sống có ý nghĩa là sống sao cho bớt khổ, thêm an vui cho mình và người.", "vo": ["vi"], "author": "Muôn Kiếp Nhân Sinh"},
 {"id": "q0014", "vi": "Nhân quả không bỏ sót một ai.\nTất cả đều được ghi lại trong dòng chảy vũ trụ.", "vo": ["vi"], "author": "Muôn Kiếp Nhân Sinh"},
 {"id": "q0015", "vi": "Muốn hiểu đời này, hãy nhìn lại những gì mình đã gieo ở quá khứ.\nMuốn biết tương lai, hãy xem mình đang sống thế nào hôm nay.", "vo": ["vi"], "author": "Muôn Kiếp Nhân Sinh"},
 {"id": "q0016", "vi": "May mắn thật sự không đến từ chờ đợi,\nmà từ sự chuẩn bị và kiên trì.", "vo": ["vi"], "author": "Vị Thần May Mắn"},
 {"id": "q0017", "vi": "Người biết tạo điều kiện thì cỏ bốn lá sẽ mọc lên dưới chân mình.", "vo": ["vi"], "author": "Vị Thần May Mắn"},
 {"id": "q0018", "vi": "Cơ hội chỉ mỉm cười với ai đã sẵn sàng.", "vo": ["vi"], "author": "Vị Thần May Mắn"},
 {"id": "q0019", "vi": "Hãy gieo hạt, chăm sóc đất, ánh sáng sẽ đến.\nĐó là cách may mắn xuất hiện.", "vo": ["vi"], "author": "Vị Thần May Mắn"},
 {"id": "q0020", "vi": "May mắn không phải phép màu,\nmà là kết quả của nỗ lực bền bỉ.", "vo": ["vi"], "author": "Vị Thần May Mắn"},
 {"id": "q0021", "vi": "Ta có thể giúp họ chết một cách bình an.\nTa có thể giúp chính ta hiểu rằng có sự chết, nghĩa là không có sợ hãi.\nChỉ có sự tiếp tục mà thôi.", "vo": ["vi"], "author": "Không Sinh Không Diệt"},
 {"id": "q0022", "vi": "Tự muôn đời tôi vẫn tự do.\nTử sinh chỉ là cửa ngõ ra vào, tử sinh là trò chơi cút bắt.\nTôi chưa bao giờ từng sinh cũng chưa bao giờ từng diệt.", "vo": ["vi"], "author": "Không Sinh Không Diệt"},
 {"id": "q0023", "vi": "Nỗi sợ hãi lớn lao nhất của chúng ta là khi chết, chúng ta sẽ trở thành không...\nBản chất thực của chúng ta là bản chất không sinh không diệt.", "vo": ["vi"], "author": "Không Sinh Không Diệt"},
 {"id": "q0024", "vi": "Chúng ta phải học cách dừng lại, để nhận ra sự sống mầu nhiệm đang có mặt trong từng khoảnh khắc.", "vo": ["vi"], "author": "Phép lạ của sự tỉnh thức"},
 {"id": "q0025", "vi": "Mỗi bước chân đi trong chánh niệm có thể đưa ta về nhà, về với chính mình.", "vo": ["vi"], "author": "Bước chân an lạc"},
 {"id": "q0026", "vi": "Trong khi thở vào, ta ý thức về toàn thân.\nTrong khi thở ra, ta làm cho thân thể mình an tịnh.", "vo": ["vi"], "author": "An lạc từng bước chân"},
 {"id": "q0027", "vi": "Ngồi cho yên, thở cho sâu, cười cho tươi — đó là thực tập của hạnh phúc.", "vo": ["vi"], "author": "Con đường mây trắng"},
 {"id": "q0028", "vi": "Chỉ cần một hơi thở chánh niệm, ta đã có thể trở về với hiện tại, nơi có bình an.", "vo": ["vi"], "author": "Từng bước nở hoa sen"},
 {"id": "q0029", "vi": "Uống một chén trà, hãy chỉ biết uống trà.\nĐi một bước chân, hãy chỉ biết đi.", "vo": ["vi"], "author": "Trà thiền"},
 {"id": "q0030", "vi": "Niệm thở giúp ta buông bỏ quá khứ, không chạy theo tương lai, an trú trọn vẹn trong giây phút này.", "vo": ["vi"], "author": "Thiền tập cho người bận rộn"},
 {"id": "q0031", "vi": "Hạnh phúc không phải là đích đến, mà là con đường ta đi trong tỉnh thức từng giây.", "vo": ["vi"], "author": "An trú trong hiện tại"},
 {"id": "q0032", "vi": "Mỗi nụ cười chánh niệm là một bông hoa an lạc nở ra trong tâm ta.", "vo": ["vi"], "author": "Hơi thở nuôi dưỡng"},
 {"id": "q0033", "vi": "Bình an không nằm ở bên ngoài, mà chính là khả năng trở về với hơi thở và nhận diện mình đang sống.", "vo": ["vi"], "author": "Học thở, học sống"},
 {"id": "q0034", "vi": "Thiền không phải là chạy trốn khỏi đời sống, mà là tiếp xúc sâu sắc với sự sống trong từng giây phút.", "vo": ["vi"], "author": "Phép lạ của sự tỉnh thức"},
 {"id": "q0035", "vi": "Mỗi hơi thở chánh niệm giống như một dòng nước mát rửa sạch lo âu và sợ hãi.", "vo": ["vi"], "author": "An lạc từng bước chân"},
 {"id": "q0036", "vi": "Khi tâm an tịnh, thế giới xung quanh cũng trở nên an lành.", "vo": ["vi"], "author": "Con đường mây trắng"},
 {"id": "q0037", "vi": "Ta có thể tìm thấy niềm vui đơn giản trong tiếng chim hót, trong gió nhẹ thoảng qua khi ta thật sự có mặt.", "vo": ["vi"], "author": "Từng bước nở hoa sen"},
 {"id": "q0038", "vi": "Sống chánh niệm là trở về với chính mình, không bị cuốn đi bởi lo toan và vọng tưởng.", "vo": ["vi"], "author": "An trú trong hiện tại"},
 {"id": "q0039", "vi": "Khi ta mỉm cười với hơi thở, thân và tâm liền trở về một mối.", "vo": ["vi"], "author": "Hơi thở nuôi dưỡng"},
 {"id": "q0040", "vi": "Ngồi xuống, dừng lại, thở vào, thở ra — chỉ vậy thôi mà ta đã có tự do.", "vo": ["vi"], "author": "Thiền tập cho người bận rộn"},
 {"id": "q0041", "vi": "Hạnh phúc lớn nhất là biết trân trọng những điều bình thường.", "vo": ["vi"], "author": "Bước chân an lạc"},
 {"id": "q0042", "vi": "Một nụ cười có thể làm tan biến căng thẳng trong ta và lan toả bình an cho người khác.", "vo": ["vi"], "author": "Phép mầu của nụ cười"},
 {"id": "q0043", "vi": "Khi đi thiền hành, đừng tìm cách đến đâu cả.\nMỗi bước chân đã là đến nơi.", "vo": ["vi"], "author": "Bước chân an lạc"},
 {"id": "q0044", "vi": "Khi ta biết cho đi một nụ cười, một lời tử tế, ta đã làm từ thiện rồi.", "vo": ["vi"], "author": "Sống đẹp mỗi ngày"},
 {"id": "q0045", "vi": "Của cải lớn nhất không phải là những gì ta giữ lại, mà là những gì ta chia sẻ.", "vo": ["vi"], "author": "Đạo đức trong đời sống"},
 {"id": "q0046", "vi": "Giúp người không chỉ làm họ hạnh phúc, mà còn mở rộng trái tim của chính ta.", "vo": ["vi"], "author": "Hạnh phúc đích thực"},
 {"id": "q0047", "vi": "Mỗi hành động nhỏ bé xuất phát từ lòng từ bi đều có thể thay đổi thế giới.", "vo": ["vi"], "author": "Đường xưa mây trắng"},
 {"id": "q0048", "vi": "Bố thí không phải là cho đi những gì ta dư thừa, mà là chia sẻ những gì ta trân quý.", "vo": ["vi"], "author": "Phật dạy về bố thí"},
 {"id": "q0049", "vi": "Khi ta biết sống vì người khác, ta cũng đang chữa lành chính mình.", "vo": ["vi"], "author": "Nẻo về của ý"},
 {"id": "q0050", "vi": "Làm từ thiện không cần nhiều tiền của, chỉ cần một tấm lòng nhân hậu.", "vo": ["vi"], "author": "Đạo Phật ứng dụng"},
 {"id": "q0051", "vi": "Người biết sống sẻ chia thì không bao giờ nghèo khó trong tâm hồn.", "vo": ["vi"], "author": "Hạt giống tâm hồn"},
 {"id": "q0052", "vi": "Hãy cho đi một chút tình thương mỗi ngày.\nChính điều đó nuôi dưỡng hạnh phúc lâu dài.", "vo": ["vi"], "author": "Hạnh phúc giản dị"},
 {"id": "q0053", "vi": "Khi mở lòng giúp người, ta cũng mở cửa trái tim để đón nhận an lạc.", "vo": ["vi"], "author": "Hơi thở nuôi dưỡng"},
 {"id": "q0054", "vi": "Khi tâm bình tĩnh, ta nhìn sự việc rõ ràng hơn và không bị cuốn theo cảm xúc.", "vo": ["vi"], "author": "An lạc từng bước chân"},
 {"id": "q0055", "vi": "Bình tĩnh không phải là thờ ơ, mà là khả năng đối diện mọi biến động với trái tim vững chãi.", "vo": ["vi"], "author": "Con đường mây trắng"},
 {"id": "q0056", "vi": "Một hơi thở sâu có thể giúp ta quay về với sự bình an trong tâm.", "vo": ["vi"], "author": "Hơi thở nuôi dưỡng"},
 {"id": "q0057", "vi": "Trong cơn giận, nếu giữ được bình tĩnh, ta đã thắng được chính mình.", "vo": ["vi"], "author": "Giữ tâm an"},
 {"id": "q0058", "vi": "Người bình tĩnh biết lắng nghe, biết thấu hiểu, và nhờ đó mà không tạo thêm khổ đau.", "vo": ["vi"], "author": "Phép lạ của sự tỉnh thức"},
 {"id": "q0059", "vi": "Tâm an thì cảnh cũng an.\nTâm động thì cảnh cũng động.", "vo": ["vi"], "author": "Thiền tập cho người bận rộn"},
 {"id": "q0060", "vi": "Sức mạnh thật sự không nằm ở quyền lực, mà ở khả năng giữ bình tĩnh giữa sóng gió.", "vo": ["vi"], "author": "Năng lượng tỉnh thức"},
 {"id": "q0061", "vi": "Khi ta ngồi yên và thở đều, sự bình tĩnh lan toả trong từng tế bào cơ thể.", "vo": ["vi"], "author": "Bước chân an lạc"},
 {"id": "q0062", "vi": "Người biết giữ bình tĩnh là người có thể tạo ra hòa bình cho người khác.", "vo": ["vi"], "author": "Nẻo về của ý"},
 {"id": "q0063", "vi": "Bình tĩnh chính là cây cầu đưa ta từ lo lắng sang bình an.", "vo": ["vi"], "author": "Hạnh phúc giản dị"},
 {"id": "q0064", "vi": "Mỗi khi ta thở trong chánh niệm, ta đang tạo ra một trường năng lượng an lạc quanh mình.", "vo": ["vi"], "author": "Năng lượng tỉnh thức"},
 {"id": "q0065", "vi": "Năng lượng chánh niệm không chỉ nuôi dưỡng ta, mà còn ôm ấp và chuyển hóa khổ đau của người khác.", "vo": ["vi"], "author": "Phép lạ của sự tỉnh thức"},
 {"id": "q0066", "vi": "Khi một nhóm người cùng ngồi thiền, năng lượng chung có thể nâng đỡ và trị liệu cho tất cả.", "vo": ["vi"], "author": "An lạc từng bước chân"},
 {"id": "q0067", "vi": "Mỗi ngày ta luyện tập một chút, lâu dần năng lượng bình an sẽ trở thành nền tảng vững chắc.", "vo": ["vi"], "author": "Bước chân an lạc"},
 {"id": "q0068", "vi": "Trường năng lượng từ bi và hiểu biết có sức mạnh làm tan biến hận thù.", "vo": ["vi"], "author": "Con đường mây trắng"},
 {"id": "q0069", "vi": "Sự luyện tập không phải để trở thành ai khác, mà để trở về chính mình.", "vo": ["vi"], "author": "Nẻo về của ý"},
 {"id": "q0070", "vi": "Khi ta ngồi xuống, buông bỏ lo toan, ta đang làm mới lại nguồn năng lượng trong thân và tâm.", "vo": ["vi"], "author": "Hơi thở nuôi dưỡng"},
 {"id": "q0071", "vi": "Thực tập mỗi ngày là gieo hạt giống an lạc, dần dần ta có cả một vườn bình yên trong tâm.", "vo": ["vi"], "author": "Hạnh phúc giản dị"},
 {"id": "q0072", "vi": "Năng lượng chánh niệm giống như ánh sáng, giúp ta thấy rõ đường đi trong đêm tối.", "vo": ["vi"], "author": "Thiền tập cho người bận rộn"},
 {"id": "q0073", "vi": "Khi thân và tâm hợp nhất trong từng động tác, mọi việc ta làm đều trở thành thiền tập.", "vo": ["vi"], "author": "Sống chậm để yêu thương"},
 {"id": "q0074", "vi": "Buông bỏ không có nghĩa là từ bỏ, mà là thôi không nắm chặt những gì gây khổ đau cho mình.", "vo": ["vi"], "author": "Con đường mây trắng"},
 {"id": "q0075", "vi": "Khi ta buông bỏ được, ta lập tức có tự do và nhẹ nhàng.", "vo": ["vi"], "author": "Phép lạ của sự tỉnh thức"},
 {"id": "q0076", "vi": "Mọi sự vật đều thay đổi, đó chính là bản chất vô thường của cuộc sống.", "vo": ["vi"], "author": "Vô thường"},
 {"id": "q0077", "vi": "Hãy trân trọng từng giây phút, vì chúng sẽ không bao giờ trở lại.", "vo": ["vi"], "author": "Hơi thở nuôi dưỡng"},
 {"id": "q0078", "vi": "Chấp nhận vô thường, ta sẽ không còn sợ mất mát.", "vo": ["vi"], "author": "Năng lượng tỉnh thức"},
 {"id": "q0079", "vi": "Khi một cánh cửa khép lại, đó cũng là lúc một cánh cửa khác mở ra.", "vo": ["vi"], "author": "Buông bỏ để an lạc"},
 {"id": "q0080", "vi": "Tất cả những gì ta có hôm nay chỉ là tạm thời, vì vậy hãy sống với lòng biết ơn.", "vo": ["vi"], "author": "Hạnh phúc giản dị"},
 {"id": "q0081", "vi": "Nỗi khổ chỉ bớt đi khi ta biết buông bỏ những gì không thật sự cần thiết.", "vo": ["vi"], "author": "Thiền tập cho người bận rộn"},
 {"id": "q0082", "vi": "Vô thường dạy ta yêu thương nhau nhiều hơn, bởi vì chẳng có gì tồn tại mãi mãi.", "vo": ["vi"], "author": "An lạc từng bước chân"},
 {"id": "q0083", "vi": "Chìa khóa của tự do là buông bỏ sự bám víu vào cái tôi và quá khứ.", "vo": ["vi"], "author": "Nẻo về của ý"},
 {"id": "q0084", "vi": "Yêu thương là khả năng nhìn sâu để hiểu, không phải chỉ để chiếm hữu.", "vo": ["vi"], "author": "Con đường mây trắng"},
 {"id": "q0085", "vi": "Khi trái tim mở ra với từ bi, ta thấy mọi người đều xứng đáng được yêu thương.", "vo": ["vi"], "author": "Năng lượng tỉnh thức"},
 {"id": "q0086", "vi": "Tình thương chân thật không đòi hỏi điều kiện, nó chỉ đơn giản là có mặt.", "vo": ["vi"], "author": "Phép lạ của sự tỉnh thức"},
 {"id": "q0087", "vi": "Người biết yêu thương bản thân mới có thể trao đi tình thương lành mạnh cho người khác.", "vo": ["vi"], "author": "Hơi thở nuôi dưỡng"},
 {"id": "q0088", "vi": "Mỗi ánh mắt cảm thông, mỗi nụ cười hiền hậu là một hạt giống từ bi gieo xuống đời.", "vo": ["vi"], "author": "An lạc từng bước chân"},
 {"id": "q0089", "vi": "Tình thương lành mạnh không ràng buộc, mà trao tặng tự do cho nhau.", "vo": ["vi"], "author": "Nẻo về của ý"},
 {"id": "q0090", "vi": "Khi ta nắm tay nhau trong chánh niệm, năng lượng thương yêu được truyền đi vô tận.", "vo": ["vi"], "author": "Bước chân an lạc"},
 {"id": "q0091", "vi": "Từ bi không phải là thương hại, mà là khả năng hiểu và muốn làm vơi bớt nỗi khổ của người khác.", "vo": ["vi"], "author": "Đạo đức trong đời sống"},
 {"id": "q0092", "vi": "Tình yêu chân thật giúp ta lớn lên, giúp người kia cũng lớn lên.", "vo": ["vi"], "author": "Hạnh phúc đích thực"},
 {"id": "q0093", "vi": "Khi nuôi dưỡng lòng từ bi, ta đang xây dựng một thế giới an lành cho tất cả.", "vo": ["vi"], "author": "Sống chậm để yêu thương"},
 {"id": "q0094", "vi": "Hạnh phúc không nằm ở tương lai hay quá khứ, mà ở giây phút hiện tại này.", "vo": ["vi"], "author": "Phép lạ của sự tỉnh thức"},
 {"id": "q0095", "vi": "Khi ta có thể mỉm cười giữa khó khăn, đó là hạnh phúc đích thực.", "vo": ["vi"], "author": "Hơi thở nuôi dưỡng"},
 {"id": "q0096", "vi": "An lạc không phải do tìm kiếm bên ngoài, mà do nuôi dưỡng bên trong.", "vo": ["vi"], "author": "Nẻo về của ý"},
 {"id": "q0097", "vi": "Hạnh phúc thật sự là khi ta biết đủ và trân trọng những gì đang có.", "vo": ["vi"], "author": "Hạnh phúc giản dị"},
 {"id": "q0098", "vi": "Mỗi bước đi trong chánh niệm là một bước đi trong hạnh phúc.", "vo": ["vi"], "author": "Bước chân an lạc"},
 {"id": "q0099", "vi": "Khi tâm dừng lại, an lạc liền có mặt.", "vo": ["vi"], "author": "An lạc từng bước chân"},
 {"id": "q0100", "vi": "Một tách trà uống trong tỉnh thức có thể mang lại niềm vui lớn hơn cả kho báu.", "vo": ["vi"], "author": "Trà thiền"},
 {"id": "q0101", "vi": "Hạnh phúc không phải là đích đến, mà là hành trình của từng hơi thở và bước chân.", "vo": ["vi"], "author": "Con đường mây trắng"},
 {"id": "q0102", "vi": "Người có an lạc trong tâm thì ở đâu cũng thấy an lành.", "vo": ["vi"], "author": "Năng lượng tỉnh thức"},
 {"id": "q0103", "vi": "Hạnh phúc giản đơn là khi ta được là chính mình, không cần phải chạy theo ai khác.", "vo": ["vi"], "author": "Sống chậm để yêu thương"},
 {"id": "q0104", "vi": "Ngồi thiền 5 phút không làm bạn giàu hơn,\nnhưng chắc chắn làm bạn ít cáu hơn.", "vo": ["vi"], "author": "Zen Vui Vẻ"},
 {"id": "q0105", "vi": "Nếu bạn nghĩ ngồi yên là lãng phí thời gian,\nthử so sánh với lúc bạn lướt điện thoại 2 tiếng xem.", "vo": ["vi"], "author": "Zen Vui Vẻ"},
 {"id": "q0106", "vi": "Đôi khi hít thở sâu không giải quyết vấn đề,\nnhưng ít nhất giúp ta không hét vào mặt người khác.", "vo": ["vi"], "author": "Zen Cười"},
 {"id": "q0107", "vi": "Thiền: nghệ thuật ngồi không làm gì\nmà vẫn trông có vẻ rất bận.", "vo": ["vi"], "author": "Zen Hóm Hỉnh"},
 {"id": "q0108", "vi": "Đi chậm lại không khiến bạn thua kém ai,\nnhưng có thể cứu đôi giày của bạn khỏi bị rách.", "vo": ["vi"], "author": "Zen Hóm Hỉnh"},
 {"id": "q0109", "vi": "Ngồi yên hít thở: free.\nĐi spa: tốn tiền.\nHiệu quả đôi khi giống nhau.", "vo": ["vi"], "author": "Zen Vui Vẻ"},
 {"id": "q0110", "vi": "Nếu bạn không thể kiểm soát cơn giận,\nthì hãy kiểm soát ít nhất… cái miệng của mình.", "vo": ["vi"], "author": "Zen Hài Hước"},
 {"id": "q0111", "vi": "Bình tĩnh không có trong siêu thị,\nnhưng bạn có thể tìm thấy ngay trong hơi thở.", "vo": ["vi"], "author": "Zen Vui Vẻ"},
 {"id": "q0112", "vi": "Đừng quá nghiêm túc.\nKhông ai thoát khỏi cuộc đời này còn sống đâu.", "vo": ["vi"], "author": "Zen Hóm Hỉnh"},
 {"id": "q0113", "vi": "Thở ra, cười một cái.\nNếu chưa thấy vui, thử thêm… trà sữa.", "vo": ["vi"], "author": "Zen Hài Hước"},
 {"id": "q0114", "vi": "Nỗi buồn nặng như tạ.\nNụ cười nhẹ như gió.\nBạn chọn mang cái nào?", "vo": ["vi"], "author": "Zen Vui Vẻ"},
 {"id": "q0115", "vi": "Đời là vô thường.\nĐừng tiếc miếng bánh — ăn ngay khi nó còn nóng.", "vo": ["vi"], "author": "Zen Cười"},
 {"id": "q0116", "vi": "Một phút giận dữ có thể làm hỏng cả ngày.\nMột phút cười có thể cứu cả tuần.", "vo": ["vi"], "author": "Zen Hóm Hỉnh"},
 {"id": "q0117", "vi": "Bạn không cần wifi để kết nối với hơi thở.", "vo": ["vi"], "author": "Zen Hài Hước"},
 {"id": "q0118", "vi": "Thiền hành: vừa đi vừa thở.\nĐừng nhầm với vừa đi vừa lướt TikTok.", "vo": ["vi"], "author": "Zen Vui Vẻ"},
 {"id": "q0119", "vi": "Nếu không có thời gian ngồi thiền 10 phút,\nhãy thử… tắt TV 10 phút.", "vo": ["vi"], "author": "Zen Hóm Hỉnh"},
 {"id": "q0120", "vi": "Hạnh phúc đơn giản:\nNgủ ngon, ăn vừa đủ, ít drama.", "vo": ["vi"], "author": "Zen Cười"},
 {"id": "q0121", "vi": "Không cần đi tìm núi để giác ngộ.\nĐôi khi rửa chén cũng đủ rồi.", "vo": ["vi"], "author": "Zen Vui Vẻ"},
 {"id": "q0122", "vi": "Chánh niệm là khả năng biết mình đang làm gì trong giây phút này.", "vo": ["vi"], "author": "Phép lạ của sự tỉnh thức"},
 {"id": "q0123", "vi": "Thở vào, tôi biết tôi đang sống.\nThở ra, tôi mỉm cười với sự sống mầu nhiệm.", "vo": ["vi"], "author": "An lạc từng bước chân"},
 {"id": "q0124", "vi": "Khi bạn uống một tách trà trong chánh niệm, cả vũ trụ có mặt trong đó.", "vo": ["vi"], "author": "Trà thiền"},
 {"id": "q0125", "vi": "Một ngày an lạc bắt đầu từ một hơi thở sâu và nụ cười nhẹ.", "vo": ["vi"], "author": "Hơi thở nuôi dưỡng"},
 {"id": "q0126", "vi": "Chánh niệm không phải là xa rời thế gian, mà là sống trọn vẹn giữa đời.", "vo": ["vi"], "author": "Con đường mây trắng"},
 {"id": "q0127", "vi": "Đi từng bước chậm rãi, ta thấy mình đang bước trên thiên đường.", "vo": ["vi"], "author": "Bước chân an lạc"},
 {"id": "q0128", "vi": "Khi ta chú ý đến từng hơi thở, ta có thể làm bạn với chính mình.", "vo": ["vi"], "author": "Thiền tập cho người bận rộn"},
 {"id": "q0129", "vi": "Giữ tâm an định là giữ được cả một thế giới bình yên trong lòng.", "vo": ["vi"], "author": "Năng lượng tỉnh thức"},
 {"id": "q0130", "vi": "Một phút chánh niệm còn quý hơn cả ngàn phút vô minh.", "vo": ["vi"], "author": "Nẻo về của ý"},
 {"id": "q0131", "vi": "Thở vào, ta thấy rõ sự sống.\nThở ra, ta thảnh thơi như mây trời.", "vo": ["vi"], "author": "Sống chậm để yêu thương"},
 {"id": "q0132", "vi": "Hạnh phúc thật sự không cần điều kiện gì ngoài sự có mặt trọn vẹn.", "vo": ["vi"], "author": "Eckhart Tolle"},
 {"id": "q0133", "vi": "An lạc có sẵn bên trong bạn, không ai có thể lấy đi.", "vo": ["vi"], "author": "Dalai Lama"},
 {"id": "q0134", "vi": "Khi ta biết trân trọng những điều nhỏ bé, hạnh phúc liền nở rộ.", "vo": ["vi"], "author": "Hạnh phúc giản dị"},
 {"id": "q0135", "vi": "Người hạnh phúc không phải người có nhiều, mà là người biết đủ.", "vo": ["vi"], "author": "Hạt giống tâm hồn"},
 {"id": "q0136", "vi": "Hãy để nụ cười dẫn đường, bạn sẽ thấy hạnh phúc ở mọi nơi.", "vo": ["vi"], "author": "Phép mầu của nụ cười"},
 {"id": "q0137", "vi": "Hạnh phúc không xa, nó bắt đầu từ một cái ôm chân thành.", "vo": ["vi"], "author": "Jon Kabat-Zinn"},
 {"id": "q0138", "vi": "Sống trọn vẹn hôm nay, bạn sẽ không hối tiếc ngày mai.", "vo": ["vi"], "author": "Hạnh phúc đích thực"},
 {"id": "q0139", "vi": "An lạc không phải là điều ta đạt được, mà là điều ta nhận ra.", "vo": ["vi"], "author": "Eckhart Tolle"},
 {"id": "q0140", "vi": "Mỗi khoảnh khắc tỉnh thức đều là một kho báu hạnh phúc.", "vo": ["vi"], "author": "Dalai Lama"},
 {"id": "q0141", "vi": "Hạnh phúc là khi bạn mỉm cười và thấy lòng mình đủ đầy.", "vo": ["vi"], "author": "Hạnh phúc giản dị"},
 {"id": "q0142", "vi": "Không cần đợi đến lúc thành công, bạn có thể hạnh phúc ngay bây giờ.", "vo": ["vi"], "author": "Ajahn Chah"},
 {"id": "q0143", "vi": "Người biết dừng lại đúng lúc mới có thể an lạc thật sự.", "vo": ["vi"], "author": "Năng lượng tỉnh thức"},
 {"id": "q0144", "vi": "Đừng tìm hạnh phúc ở chân trời xa xôi, nó đang nở ngay dưới chân bạn.", "vo": ["vi"], "author": "Bước chân an lạc"},
 {"id": "q0145", "vi": "An lạc không phải trốn tránh khổ đau, mà là khả năng ôm ấp nó.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0146", "vi": "Nếu bạn có thể mỉm cười với chính mình, bạn đã tìm thấy hạnh phúc.", "vo": ["vi"], "author": "Hơi thở nuôi dưỡng"},
 {"id": "q0147", "vi": "Hạnh phúc giản đơn: một hơi thở sâu, một nụ cười nhẹ.", "vo": ["vi"], "author": "Sống chậm để yêu thương"},
 {"id": "q0148", "vi": "Người hạnh phúc là người biến mọi giây phút bình thường thành đặc biệt.", "vo": ["vi"], "author": "Hạnh phúc giản dị"},
 {"id": "q0149", "vi": "Hãy thưởng thức hiện tại như một bản nhạc quý giá.", "vo": ["vi"], "author": "Eckhart Tolle"},
 {"id": "q0150", "vi": "Hạnh phúc không bao giờ ở ngoài kia, nó luôn ở ngay trong bạn.", "vo": ["vi"], "author": "Dalai Lama"},
 {"id": "q0151", "vi": "Người biết chia sẻ an lạc của mình sẽ nhân đôi hạnh phúc.", "vo": ["vi"], "author": "Hạnh phúc đích thực"},
 {"id": "q0152", "vi": "Mỗi bước chân trong chánh niệm đưa ta trở về quê hương của chính mình.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0153", "vi": "Hạnh phúc không phải là đi tìm thêm, mà là buông bớt.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0154", "vi": "Nụ cười chánh niệm là hoa trái của bình an.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0155", "vi": "Mỗi hơi thở chánh niệm có thể làm tan biến một nỗi buồn.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0156", "vi": "Khi ta biết dừng lại, hạnh phúc liền có mặt.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0157", "vi": "Đừng chạy trốn khổ đau, hãy ôm ấp nó bằng hơi thở tỉnh thức.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0158", "vi": "Đi như thể bạn đang hôn mặt đất bằng bàn chân.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0159", "vi": "Không ai có thể lấy đi an lạc của bạn, nếu bạn không trao nó đi.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0160", "vi": "Khi ta biết lắng nghe bằng trái tim, sự hiểu biết sẽ nở hoa.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0161", "vi": "Chánh niệm giúp ta sống sâu sắc, không bị cuốn đi bởi quá khứ hay tương lai.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0162", "vi": "An lạc có mặt khi ta biết dừng lại và thở sâu.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0163", "vi": "Mỗi nụ cười là một lời mời gọi hạnh phúc đến.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0164", "vi": "Thực tập buông bỏ giúp ta nhẹ nhàng như mây trắng.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0165", "vi": "Đời sống chỉ thực sự có mặt trong hiện tại này.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0166", "vi": "Nếu bạn biết trân quý từng hơi thở, bạn sẽ thấy đời sống nhiệm mầu.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0167", "vi": "Thở vào tôi làm mới thân tâm.\nThở ra tôi mỉm cười.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0168", "vi": "Mỗi bước đi tỉnh thức là một lời cầu nguyện cho hòa bình.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0169", "vi": "Chánh niệm là năng lượng giúp ta trở về với chính mình.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0170", "vi": "Không có con đường đi tới hạnh phúc.\nHạnh phúc chính là con đường.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0171", "vi": "Tình thương chân thật trao đi tự do chứ không ràng buộc.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0172", "vi": "Đừng cố gắng xua đuổi khổ đau, hãy ôm lấy nó với chánh niệm.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0173", "vi": "Khi ta thở chánh niệm, từng tế bào đều được chữa lành.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0174", "vi": "Hạnh phúc đích thực đến từ khả năng tiếp xúc với hiện tại.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0175", "vi": "Một nụ cười cũng có thể cứu vãn một ngày mưa bão.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0176", "vi": "Ngồi yên không phải để trốn chạy, mà để nhìn rõ sự thật.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0177", "vi": "An lạc có mặt trong từng bước chân vững chãi.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0178", "vi": "Khi trái tim mở ra, thế giới cũng mở ra.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0179", "vi": "Hãy sống như thể từng ngày là một món quà.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0180", "vi": "Thở vào thấy tôi còn sống.\nThở ra thấy tôi hạnh phúc.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0181", "vi": "Khi biết quay về với hơi thở, ta có thể an trú ngay giữa bão tố.", "vo": ["vi"], "author": "Thích Nhất Hạnh"},
 {"id": "q0182", "en": "Realize deeply that the present moment is all you ever have.", "vo": ["en"], "author": "Eckhart Tolle"},
 {"id": "q0183", "en": "The primary cause of unhappiness is never the situation but your thoughts about it.", "vo": ["en"], "author": "Eckhart Tolle"},
 {"id": "q0184", "en": "You find peace not by rearranging the circumstances of your life, but by realizing who you are at the deepest level.", "vo": ["en"], "author": "Eckhart Tolle"},
 {"id": "q0185", "en": "Acknowledging the good that you already have in your life is the foundation for all abundance.", "vo": ["en"], "author": "Eckhart Tolle"},
 {"id": "q0186", "en": "Life will give you whatever experience is most helpful for the evolution of your consciousness.", "vo": ["en"], "author": "Eckhart Tolle"},
 {"id": "q0187", "en": "Sometimes letting things go is an act of far greater power than defending or hanging on.", "vo": ["en"], "author": "Eckhart Tolle"},
 {"id": "q0188", "en": "To love is to recognize yourself in another.", "vo": ["en"], "author": "Eckhart Tolle"},
 {"id": "q0189", "en": "Don’t let a mad world tell you that success is anything other than a successful present moment.", "vo": ["en"], "author": "Eckhart Tolle"},
 {"id": "q0190", "en": "If you get the inside right, the outside will fall into place.", "vo": ["en"], "author": "Eckhart Tolle"},
 {"id": "q0191", "en": "Stress is caused by being here but wanting to be there.", "vo": ["en"], "author": "Eckhart Tolle"},
 {"id": "q0192", "en": "The purpose of our lives is to be happy.", "vo": ["en"], "author": "Dalai Lama"},
 {"id": "q0193", "en": "Be kind whenever possible. It is always possible.", "vo": ["en"], "author": "Dalai Lama"},
 {"id": "q0194", "en": "If you want others to be happy, practice compassion. If you want to be happy, practice compassion.", "vo": ["en"], "author": "Dalai Lama"},
 {"id": "q0195", "en": "Happiness is not something ready-made. It comes from your own actions.", "vo": ["en"], "author": "Dalai Lama"},
 {"id": "q0196", "en": "Our prime purpose in this life is to help others. And if you can’t help them, at least don’t hurt them.", "vo": ["en"], "author": "Dalai Lama"},
 {"id": "q0197", "en": "Love and compassion are necessities, not luxuries. Without them humanity cannot survive.", "vo": ["en"], "author": "Dalai Lama"},
 {"id": "q0198", "en": "Remember that sometimes not getting what you want is a wonderful stroke of luck.", "vo": ["en"], "author": "Dalai Lama"},
 {"id": "q0199", "en": "When you practice gratefulness, there is a sense of respect toward others.", "vo": ["en"], "author": "Dalai Lama"},
 {"id": "q0200", "en": "Choose to be optimistic, it feels better.", "vo": ["en"], "author": "Dalai Lama"},
 {"id": "q0201", "en": "Compassion and tolerance are not a sign of weakness, but a sign of strength.", "vo": ["en"], "author": "Dalai Lama"},
 {"id": "q0202", "en": "When you slow down, you see the beauty in small things.", "vo": ["en"], "author": "Haemin Sunim"},
 {"id": "q0203", "en": "Having a lot does not make us happy. Enjoying little things does.", "vo": ["en"], "author": "Haemin Sunim"},
 {"id": "q0204", "en": "Do not try to control everything. Relax, breathe, let life unfold.", "vo": ["en"], "author": "Haemin Sunim"},
 {"id": "q0205", "en": "Sometimes the most productive thing you can do is relax.", "vo": ["en"], "author": "Haemin Sunim"},
 {"id": "q0206", "en": "Don’t compare your life with others. There’s no competition in destiny.", "vo": ["en"], "author": "Haemin Sunim"},
 {"id": "q0207", "en": "Even when life is full of burdens, if your heart is at ease, your world becomes beautiful.", "vo": ["en"], "author": "Haemin Sunim"},
 {"id": "q0208", "en": "When you learn to let go, you find peace.", "vo": ["en"], "author": "Haemin Sunim"},
 {"id": "q0209", "en": "Be kind to yourself, then you can be truly kind to others.", "vo": ["en"], "author": "Haemin Sunim"},
 {"id": "q0210", "en": "Happiness is not far away; it is within you, waiting to be noticed.", "vo": ["en"], "author": "Haemin Sunim"},
 {"id": "q0211", "en": "Do everything with a mind of compassion, and life becomes lighter.", "vo": ["en"], "author": "Haemin Sunim"},
 {"id": "q0212", "en": "You can’t stop the waves, but you can learn to surf.", "vo": ["en"], "author": "Jon Kabat-Zinn"},
 {"id": "q0213", "en": "Mindfulness means paying attention in a particular way: on purpose, in the present moment, and non-judgmentally.", "vo": ["en"], "author": "Jon Kabat-Zinn"},
 {"id": "q0214", "en": "Wherever you go, there you are.", "vo": ["en"], "author": "Jon Kabat-Zinn"},
 {"id": "q0215", "en": "Each moment is a chance to start anew.", "vo": ["en"], "author": "Jon Kabat-Zinn"},
 {"id": "q0216", "en": "Awareness is healing.", "vo": ["en"], "author": "Jon Kabat-Zinn"},
 {"id": "q0217", "en": "Small steps in awareness bring big changes over time.", "vo": ["en"], "author": "Jon Kabat-Zinn"},
 {"id": "q0218", "en": "Mindfulness is the aware, balanced acceptance of the present experience.", "vo": ["en"], "author": "Jon Kabat-Zinn"},
 {"id": "q0219", "en": "The little things? The little moments? They are not little.", "vo": ["en"], "author": "Jon Kabat-Zinn"},
 {"id": "q0220", "en": "In letting go of striving, we discover peace.", "vo": ["en"], "author": "Jon Kabat-Zinn"},
 {"id": "q0221", "en": "There is no place to go, just this moment.", "vo": ["en"], "author": "Jon Kabat-Zinn"},
 {"id": "q0222", "en": "Nothing ever goes away until it has taught us what we need to know.", "vo": ["en"], "author": "Pema Chödrön"},
 {"id": "q0223", "en": "You are the sky. Everything else – it’s just the weather.", "vo": ["en"], "author": "Pema Chödrön"},
 {"id": "q0224", "en": "Fear is a natural reaction to moving closer to the truth.", "vo": ["en"], "author": "Pema Chödrön"},
 {"id": "q0225", "en": "Compassion for others begins with kindness to ourselves.", "vo": ["en"], "author": "Pema Chödrön"},
 {"id": "q0226", "en": "We can meet life as it is, not as we wish it to be.", "vo": ["en"], "author": "Pema Chödrön"},
 {"id": "q0227", "en": "Letting go gives us freedom, and freedom is the only condition for happiness.", "vo": ["en"], "author": "Pema Chödrön"},
 {"id": "q0228", "en": "When we resist change, we suffer. When we accept change, we grow.", "vo": ["en"], "author": "Pema Chödrön"},
 {"id": "q0229", "en": "Be fully present. Let your heart be touched by life.", "vo": ["en"], "author": "Pema Chödrön"},
 {"id": "q0230", "en": "The essence of bravery is being without self-deception.", "vo": ["en"], "author": "Pema Chödrön"},
 {"id": "q0231", "en": "Our true nature is like the sky—open, vast, and limitless.", "vo": ["en"], "author": "Pema Chödrön"},
 {"id": "q0232", "en": "The trouble is, you think you have time.", "vo": ["en"], "author": "Jack Kornfield"},
 {"id": "q0233", "en": "In the end, just three things matter: how well we have lived, how well we have loved, how well we have learned to let go.", "vo": ["en"], "author": "Jack Kornfield"},
 {"id": "q0234", "en": "Peace comes when our hearts are open to the flow of life.", "vo": ["en"], "author": "Jack Kornfield"},
 {"id": "q0235", "en": "With mindfulness, we discover that our life is already complete.", "vo": ["en"], "author": "Jack Kornfield"},
 {"id": "q0236", "en": "Forgiveness is giving up the hope of a better past.", "vo": ["en"], "author": "Jack Kornfield"},
 {"id": "q0237", "en": "Happiness comes when we stop searching and start living.", "vo": ["en"], "author": "Jack Kornfield"},
 {"id": "q0238", "en": "Each kind act is a ripple that spreads through the world.", "vo": ["en"], "author": "Jack Kornfield"},
 {"id": "q0239", "en": "We can learn to live more fully by opening to every experience.", "vo": ["en"], "author": "Jack Kornfield"},
 {"id": "q0240", "en": "Mindfulness is simply being aware of what is happening right now without wishing it were different.", "vo": ["en"], "author": "Jack Kornfield"},
 {"id": "q0241", "en": "The heart is like a garden. It can grow compassion or fear, resentment or love.", "vo": ["en"], "author": "Jack Kornfield"},
 {"id": "q0242", "en": "Lovingkindness is the practice of offering friendship to yourself and others.", "vo": ["en"], "author": "Sharon Salzberg"},
 {"id": "q0243", "en": "You are a person worthy of love and belonging.", "vo": ["en"], "author": "Sharon Salzberg"},
 {"id": "q0244", "en": "Happiness is not found through changing our external world, but through changing our relationship to it.", "vo": ["en"], "author": "Sharon Salzberg"},
 {"id": "q0245", "en": "You yourself, as much as anybody in the universe, deserve your love and affection.", "vo": ["en"], "author": "Sharon Salzberg"},
 {"id": "q0246", "en": "Kindness is not a luxury; it is a necessity of life.", "vo": ["en"], "author": "Sharon Salzberg"},
 {"id": "q0247", "en": "Mindfulness isn’t difficult. What’s difficult is to remember to be mindful.", "vo": ["en"], "author": "Sharon Salzberg"},
 {"id": "q0248", "en": "Equanimity means caring, but still having the ability to say no.", "vo": ["en"], "author": "Sharon Salzberg"},
 {"id": "q0249", "en": "Every act of kindness grows the spirit and strengthens the heart.", "vo": ["en"], "author": "Sharon Salzberg"},
 {"id": "q0250", "en": "Real love is not about perfection. It is about acceptance.", "vo": ["en"], "author": "Sharon Salzberg"},
 {"id": "q0251", "en": "Generosity is an inner quality that arises when we allow compassion to guide us.", "vo": ["en"], "author": "Sharon Salzberg"},
 {"id": "q0252", "en": "You have power over your mind – not outside events. Realize this, and you will find strength.", "vo": ["en"], "author": "Marcus Aurelius"},
 {"id": "q0253", "en": "The happiness of your life depends upon the quality of your thoughts.", "vo": ["en"], "author": "Marcus Aurelius"},
 {"id": "q0254", "en": "If it is not right, do not do it; if it is not true, do not say it.", "vo": ["en"], "author": "Marcus Aurelius"},
 {"id": "q0255", "en": "When you arise in the morning, think of what a precious privilege it is to be alive.", "vo": ["en"], "author": "Marcus Aurelius"},
 {"id": "q0256", "en": "He who lives in harmony with himself lives in harmony with the universe.", "vo": ["en"], "author": "Marcus Aurelius"},
 {"id": "q0257", "en": "You could leave life right now. Let that determine what you do and say and think.", "vo": ["en"], "author": "Marcus Aurelius"},
 {"id": "q0258", "en": "Very little is needed to make a happy life; it is all within yourself.", "vo": ["en"], "author": "Marcus Aurelius"},
 {"id": "q0259", "en": "Loss is nothing else but change, and change is Nature’s delight.", "vo": ["en"], "author": "Marcus Aurelius"},
 {"id": "q0260", "en": "Waste no more time arguing what a good man should be. Be one.", "vo": ["en"], "author": "Marcus Aurelius"},
 {"id": "q0261", "en": "Dwell on the beauty of life. Watch the stars, and see yourself running with them.", "vo": ["en"], "author": "Marcus Aurelius"},
 {"id": "q0262", "en": "It is not that we have a short time to live, but that we waste a lot of it.", "vo": ["en"], "author": "Seneca"},
 {"id": "q0263", "en": "Life is long if you know how to use it.", "vo": ["en"], "author": "Seneca"},
 {"id": "q0264", "en": "We suffer more often in imagination than in reality.", "vo": ["en"], "author": "Seneca"},
 {"id": "q0265", "en": "Begin at once to live, and count each day as a separate life.", "vo": ["en"], "author": "Seneca"},
 {"id": "q0266", "en": "It is not the man who has too little, but the man who craves more, that is poor.", "vo": ["en"], "author": "Seneca"},
 {"id": "q0267", "en": "Associate with people who are likely to improve you.", "vo": ["en"], "author": "Seneca"},
 {"id": "q0268", "en": "True happiness is to enjoy the present without anxious dependence upon the future.", "vo": ["en"], "author": "Seneca"},
 {"id": "q0269", "en": "It is the power of the mind to be unconquerable.", "vo": ["en"], "author": "Seneca"},
 {"id": "q0270", "en": "He who is brave is free.", "vo": ["en"], "author": "Seneca"},
 {"id": "q0271", "en": "While we wait for life, life passes.", "vo": ["en"], "author": "Seneca"},
 {"id": "q0272", "en": "Our life is frittered away by detail. Simplify, simplify.", "vo": ["en"], "author": "Henry David Thoreau"},
 {"id": "q0273", "en": "Go confidently in the direction of your dreams. Live the life you have imagined.", "vo": ["en"], "author": "Henry David Thoreau"},
 {"id": "q0274", "en": "Rather than love, than money, than fame, give me truth.", "vo": ["en"], "author": "Henry David Thoreau"},
 {"id": "q0275", "en": "What lies behind us and what lies ahead of us are tiny matters compared to what lies within us.", "vo": ["en"], "author": "Henry David Thoreau"},
 {"id": "q0276", "en": "Heaven is under our feet as well as over our heads.", "vo": ["en"], "author": "Henry David Thoreau"},
 {"id": "q0277", "en": "Live in each season as it passes; breathe the air, drink the drink, taste the fruit.", "vo": ["en"], "author": "Henry David Thoreau"},
 {"id": "q0278", "en": "The price of anything is the amount of life you exchange for it.", "vo": ["en"], "author": "Henry David Thoreau"},
 {"id": "q0279", "en": "This world is but a canvas to our imagination.", "vo": ["en"], "author": "Henry David Thoreau"},
 {"id": "q0280", "en": "Only that day dawns to which we are awake.", "vo": ["en"], "author": "Henry David Thoreau"},
 {"id": "q0281", "en": "Things do not change; we change.", "vo": ["en"], "author": "Henry David Thoreau"},
 {"id": "q0282", "en": "The wound is the place where the Light enters you.", "vo": ["en"], "author": "Rumi"},
 {"id": "q0283", "en": "Do not get lost in your pain, know that one day your pain will become your cure.", "vo": ["en"], "author": "Rumi"},
 {"id": "q0284", "en": "Don’t get too comfortable. Every moment life is shifting.", "vo": ["en"], "author": "Rumi"},
 {"id": "q0285", "en": "You are not a drop in the ocean. You are the entire ocean in a drop.", "vo": ["en"], "author": "Rumi"},
 {"id": "q0286", "en": "Try to accept the changing seasons of your heart, even as you have always accepted the passing of time.", "vo": ["en"], "author": "Rumi"},
 {"id": "q0287", "en": "When the soul lies down in that grass, the world is too full to talk about.", "vo": ["en"], "author": "Rumi"},
 {"id": "q0288", "en": "Be like a tree and let the dead leaves drop.", "vo": ["en"], "author": "Rumi"},
 {"id": "q0289", "en": "Raise your words, not voice. It is rain that grows flowers, not thunder.", "vo": ["en"], "author": "Rumi"},
 {"id": "q0290", "en": "Stop acting so small. You are the universe in ecstatic motion.", "vo": ["en"], "author": "Rumi"},
 {"id": "q0291", "en": "Silence is the language of God, all else is poor translation.", "vo": ["en"], "author": "Rumi"},
 {"id": "q0292", "en": "Your children are not your children. They are the sons and daughters of Life's longing for itself.", "vo": ["en"], "author": "Khalil Gibran"},
 {"id": "q0293", "en": "Work is love made visible.", "vo": ["en"], "author": "Khalil Gibran"},
 {"id": "q0294", "en": "Out of suffering have emerged the strongest souls; the most massive characters are seared with scars.", "vo": ["en"], "author": "Khalil Gibran"},
 {"id": "q0295", "en": "Beauty is eternity gazing at itself in a mirror.", "vo": ["en"], "author": "Khalil Gibran"},
 {"id": "q0296", "en": "Generosity is giving more than you can, and pride is taking less than you need.", "vo": ["en"], "author": "Khalil Gibran"},
 {"id": "q0297", "en": "Let there be spaces in your togetherness, and let the winds of the heavens dance between you.", "vo": ["en"], "author": "Khalil Gibran"},
 {"id": "q0298", "en": "Your living is determined not so much by what life brings to you, as by the attitude you bring to life.", "vo": ["en"], "author": "Khalil Gibran"},
 {"id": "q0299", "en": "Trust in dreams, for in them is hidden the gate to eternity.", "vo": ["en"], "author": "Khalil Gibran"},
 {"id": "q0300", "en": "Ever has it been that love knows not its own depth until the hour of separation.", "vo": ["en"], "author": "Khalil Gibran"},
 {"id": "q0301", "en": "In the sweetness of friendship let there be laughter, and sharing of pleasures.", "vo": ["en"], "author": "Khalil Gibran"},
 {"id": "q0302", "vi": "Khi học Phật Pháp, chúng ta phải làm cách nào để giáo lý của Bụt giúp cho tâm tư ta nhẹ nhàng hơn, chứ không làm cho ta nặng nề thêm...", "vo": ["vi", "en"], "en": "When studying the Dharma, we must find ways so that the teachings of the Buddha make our mind lighter, not heavier...", "author": "Thích Nhất Hạnh"},
 {"id": "q0303", "vi": "Qua tình thương của tôi dành cho bạn, tôi muốn bày tỏ tình thương của tôi đối với toàn bộ vũ trụ...", "vo": ["vi", "en"], "en": "Through my love for you, I want to express my love for the whole universe...", "author": "Thích Nhất Hạnh"},
 {"id": "q0304", "vi": "Thức dậy miệng mỉm cười. Hăm bốn giờ tinh khôi. Xin nguyện sống trọn vẹn...", "vo": ["vi", "en"], "en": "Waking up this morning, I smile. Twenty-four brand new hours are before me...", "author": "Thích Nhất Hạnh"},
 {"id": "q0305", "vi": "Bông hoa không thể tự nó có mặt được... Hiện hữu nghĩa là cùng hiện hữu là tương tức...", "vo": ["vi", "en"], "en": "A flower cannot exist by itself... To be means to inter-be...", "author": "Thích Nhất Hạnh"},
 {"id": "q0306", "vi": "Hãy là chính mình — đừng cố gắng trở thành ai khác.", "vo": ["vi", "en"], "en": "Be — don't try to become.", "author": "Osho"},
 {"id": "q0307", "vi": "Cuộc sống bắt đầu nơi nỗi sợ chấm dứt.", "vo": ["vi", "en"], "en": "Life begins where fear ends.", "author": "Osho"},
 {"id": "q0308", "vi": "Sự thật không phải là điều tồn tại bên ngoài để được khám phá, mà là điều bên trong cần được nhận ra.", "vo": ["vi", "en"], "en": "Truth is not something outside to be discovered, it is something inside to be realized.", "author": "Osho"},
 {"id": "q0309", "vi": "Tâm trí là người phục vụ tuyệt vời, nhưng là ông chủ nguy hiểm.", "vo": ["vi", "en"], "en": "The mind is a beautiful servant, but a dangerous master.", "author": "Osho"},
 {"id": "q0310", "vi": "Đừng tìm kiếm, đừng truy hỏi, đừng gõ cửa, đừng đòi hỏi — hãy thư giãn. Khi bạn thư giãn, nó sẽ đến.", "vo": ["vi", "en"], "en": "Don’t seek, don’t search, don’t ask, don’t knock, don’t demand — relax. If you relax, it comes.", "author": "Osho"},
 {"id": "q0311", "vi": "Khi bạn nhận thức về tâm trí, bạn sẽ kinh ngạc... khi nhận thức đạt 100%, tâm trí hoàn toàn lặng yên.", "vo": ["vi", "en"], "en": "When you become aware of the mind... when awareness is one hundred percent, the mind is utterly silent.", "author": "Osho"},
 {"id": "q0312", "vi": "Hãy quan sát cơ thể bạn trong từng hành động — đi, ngồi, thở. Đừng để mình hoạt động như một kẻ mộng du.", "vo": ["vi", "en"], "en": "Observe your body in every act — walking, sitting, breathing. Don’t let yourself act like a sleepwalker.", "author": "Osho"},
 {"id": "q0313", "vi": "Khoảnh khắc bạn trở thành nhân chứng cho tâm trí, bạn không còn bị tâm trí chi phối nữa.", "vo": ["vi", "en"], "en": "The moment you become a witness to the mind, you are no longer dominated by it.", "author": "Osho"},
 {"id": "q0314", "vi": "Tỉnh thức là chìa khóa duy nhất để sống cân bằng.", "vo": ["vi", "en"], "en": "Awareness is the only key to living in balance.", "author": "Osho"},
 {"id": "q0315", "vi": "Thiền không phải là kỹ thuật, mà là sự sống với trọn vẹn tỉnh thức trong từng giây phút.", "vo": ["vi", "en"], "en": "Meditation is not a technique but a way of life — living with total awareness in each moment.", "author": "Osho"},
 {"id": "q0316", "vi": "Ngồi im lặng, không làm gì, mùa xuân đến và cỏ mọc lên.", "vo": ["vi", "en"], "en": "Sitting silently, doing nothing, spring comes and the grass grows by itself.", "author": "Osho"},
 {"id": "q0317", "vi": "Thiền là trạng thái tự nhiên của sự tỉnh thức.", "vo": ["vi", "en"], "en": "Meditation is the natural state of awareness.", "author": "Osho"},
 {"id": "q0318", "vi": "Người thực sự thiền không cố gắng thay đổi thế giới, người đó đơn giản sống trong nhận thức.", "vo": ["vi", "en"], "en": "The truly meditative person does not try to change the world, he simply lives in awareness.", "author": "Osho"},
 {"id": "q0319", "vi": "Khi bạn quan sát hơi thở, bạn trở về với hiện tại.", "vo": ["vi", "en"], "en": "When you watch your breath, you return to the present moment.", "author": "Osho"},
 {"id": "q0320", "vi": "Ý thức là ngọn đèn soi sáng bóng tối của tâm trí.", "vo": ["vi", "en"], "en": "Consciousness is the lamp that illuminates the darkness of the mind.", "author": "Osho"},
 {"id": "q0321", "vi": "Thiền là chấp nhận tất cả những gì đang có mà không phán xét.", "vo": ["vi", "en"], "en": "Meditation is accepting everything that is without judgment.", "author": "Osho"},
 {"id": "q0322", "vi": "Thiền là buông bỏ quá khứ và tương lai, sống trong hiện tại.", "vo": ["vi", "en"], "en": "Meditation is letting go of the past and the future, living in the present.", "author": "Osho"},
 {"id": "q0323", "vi": "Người tỉnh thức nhìn sự việc như chúng là, không qua lăng kính của ký ức hay mong đợi.", "vo": ["vi", "en"], "en": "The awakened one sees things as they are, without the lenses of memory or expectation.", "author": "Osho"},
 {"id": "q0324", "vi": "Thiền không làm bạn trở thành người khác, nó đưa bạn về chính bạn.", "vo": ["vi", "en"], "en": "Meditation does not make you someone else, it brings you back to yourself.", "author": "Osho"},
 {"id": "q0325", "vi": "Khi bạn nhận thức, tâm trí trở thành công cụ, không còn là kẻ chủ.", "vo": ["vi", "en"], "en": "When you are aware, the mind becomes a tool, no longer the master.", "author": "Osho"},
 {"id": "q0326", "vi": "Khoảnh khắc tỉnh thức, bạn chạm vào sự bất tử.", "vo": ["vi", "en"], "en": "In the moment of awareness, you touch the immortal.", "author": "Osho"},
 {"id": "q0327", "vi": "Thiền là sự trống rỗng đầy ánh sáng.", "vo": ["vi", "en"], "en": "Meditation is emptiness filled with light.", "author": "Osho"},
 {"id": "q0328", "vi": "Quan sát mà không dính mắc là cốt lõi của thiền.", "vo": ["vi", "en"], "en": "Watching without attachment is the essence of meditation.", "author": "Osho"},
 {"id": "q0329", "vi": "Khi bạn im lặng bên trong, cả vũ trụ cất tiếng.", "vo": ["vi", "en"], "en": "When you are silent within, the whole universe speaks.", "author": "Osho"},
 {"id": "q0330", "vi": "Thiền là chết đi cái cũ để cái mới nảy sinh.", "vo": ["vi", "en"], "en": "Meditation is dying to the old so that the new can be born.", "author": "Osho"},
 {"id": "q0331", "vi": "Tỉnh thức biến mỗi khoảnh khắc thành một phép màu.", "vo": ["vi", "en"], "en": "Awareness turns every moment into a miracle.", "author": "Osho"},
 {"id": "q0332", "vi": "Người sống trong tỉnh thức không tìm kiếm hạnh phúc, họ chính là hạnh phúc.", "vo": ["vi", "en"], "en": "The one who lives in awareness does not seek happiness, he is happiness.", "author": "Osho"},
 {"id": "q0333", "vi": "Thiền là nghệ thuật của sự hiện diện.", "vo": ["vi", "en"], "en": "Meditation is the art of presence.", "author": "Osho"},
 {"id": "q0334", "vi": "Tỉnh thức là thấy, không phải suy nghĩ.", "vo": ["vi", "en"], "en": "Awareness is seeing, not thinking.", "author": "Osho"},
 {"id": "q0335", "vi": "Khi bạn quan sát mà không đặt tên, bạn đang thiền.", "vo": ["vi", "en"], "en": "When you observe without naming, you are meditating.", "author": "Osho"},
 {"id": "q0336", "vi": "Thiền là hương thơm của sự tĩnh lặng bên trong.", "vo": ["vi", "en"], "en": "Meditation is the fragrance of inner silence.", "author": "Osho"},
 {"id": "q0337", "vi": "Không có con đường tới thiền, thiền chính là con đường.", "vo": ["vi", "en"], "en": "There is no path to meditation, meditation is the path.", "author": "Osho"},
 {"id": "q0338", "vi": "Khi bạn tỉnh thức, mọi hành động đều trở thành thiêng liêng.", "vo": ["vi", "en"], "en": "When you are aware, every act becomes sacred.", "author": "Osho"},
 {"id": "q0339", "vi": "Tỉnh thức là nền tảng của mọi tự do.", "vo": ["vi", "en"], "en": "Awareness is the foundation of all freedom.", "author": "Osho"},
 {"id": "q0340", "vi": "Thiền là sự sống động không mục tiêu.", "vo": ["vi", "en"], "en": "Meditation is aliveness without a goal.", "author": "Osho"},
 {"id": "q0341", "vi": "Tỉnh thức là ánh sáng xua tan bóng tối vô minh.", "vo": ["vi", "en"], "en": "Awareness is the light that dispels the darkness of ignorance.", "author": "Osho"},
 {"id": "q0342", "vi": "Thiền là sự trở về với nhà, về với chính mình.", "vo": ["vi", "en"], "en": "Meditation is coming home, back to yourself.", "author": "Osho"},
 {"id": "q0343", "vi": "Người thiền là người sống trong hiện tại, không bị quá khứ hay tương lai trói buộc.", "vo": ["vi", "en"], "en": "The meditator is one who lives in the present, not bound by past or future.", "author": "Osho"},
 {"id": "q0344", "vi": "Thiền là không gian nơi cái tôi tan biến.", "vo": ["vi", "en"], "en": "Meditation is the space where the ego disappears.", "author": "Osho"},
 {"id": "q0345", "vi": "Người sống trong thiền không làm gì đặc biệt, nhưng mọi điều người đó làm đều trở nên đặc biệt.", "vo": ["vi", "en"], "en": "The one who lives in meditation does nothing special, but everything he does becomes special.", "author": "Osho"},
 {"id": "q0346", "vi": "Tỉnh thức là con đường duy nhất dẫn đến giác ngộ.", "vo": ["vi", "en"], "en": "Awareness is the only path to enlightenment.", "author": "Osho"},
 {"id": "q0347", "vi": "Thiền là dòng sông đưa bạn tới đại dương của chính mình.", "vo": ["vi", "en"], "en": "Meditation is the river that leads you to the ocean of yourself.", "author": "Osho"},
 {"id": "q0348", "vi": "Nếu bạn chưa yêu chính mình, bạn sẽ không bao giờ biết yêu người khác.", "vo": ["vi", "en"], "en": "If you have not loved yourself, you cannot love anybody else.", "author": "Osho"},
 {"id": "q0349", "vi": "Tình yêu không phải là một mối quan hệ, tình yêu là trạng thái của sự hiện hữu.", "vo": ["vi", "en"], "en": "Love is not a relationship, love is a state of being.", "author": "Osho"},
 {"id": "q0350", "vi": "Khi bạn yêu, bạn trao tự do, không phải xiềng xích.", "vo": ["vi", "en"], "en": "When you love, you give freedom, not chains.", "author": "Osho"},
 {"id": "q0351", "vi": "Nếu bạn yêu một bông hoa, đừng hái nó. Hãy để nó sống, vì yêu không phải chiếm hữu mà là trân trọng.", "vo": ["vi", "en"], "en": "If you love a flower, don’t pick it. Let it be. Love is not about possession, it is about appreciation.", "author": "Osho"},
 {"id": "q0352", "vi": "Tình yêu đích thực không đòi hỏi gì. Nó chỉ chia sẻ.", "vo": ["vi", "en"], "en": "True love demands nothing. It only shares.", "author": "Osho"},
 {"id": "q0353", "vi": "Tình yêu biến mọi thứ thành thiêng liêng.", "vo": ["vi", "en"], "en": "Love makes everything sacred.", "author": "Osho"},
 {"id": "q0354", "vi": "Người biết yêu không bao giờ cô đơn, bởi tình yêu chính là sự kết nối với toàn thể.", "vo": ["vi", "en"], "en": "One who loves is never lonely, because love is a connection with the whole.", "author": "Osho"},
 {"id": "q0355", "vi": "Tình yêu là cầu nối duy nhất giữa bạn và sự sống.", "vo": ["vi", "en"], "en": "Love is the only bridge between you and life.", "author": "Osho"},
 {"id": "q0356", "vi": "Tình yêu là cánh cửa mở vào cái vĩnh hằng.", "vo": ["vi", "en"], "en": "Love is the door to the eternal.", "author": "Osho"},
 {"id": "q0357", "vi": "Người biết yêu không sở hữu, người ấy trao không gian để người khác nở hoa.", "vo": ["vi", "en"], "en": "The one who loves does not possess; he gives space for the other to blossom.", "author": "Osho"},
 {"id": "q0358", "vi": "Tình yêu không bao giờ có thể được học; nó đến như một mưa rào khi bạn mở lòng.", "vo": ["vi", "en"], "en": "Love can never be learned; it comes as a shower when you open your heart.", "author": "Osho"},
 {"id": "q0359", "vi": "Trong tình yêu, hai người vẫn là hai, nhưng cùng nhau tạo ra một không gian thứ ba của hòa hợp.", "vo": ["vi", "en"], "en": "In love, two remain two, but together they create a third space of harmony.", "author": "Osho"},
 {"id": "q0360", "vi": "Tình yêu không phải là sự phụ thuộc; tình yêu là hai tự do gặp nhau.", "vo": ["vi", "en"], "en": "Love is not dependence; love is the meeting of two freedoms.", "author": "Osho"},
 {"id": "q0361", "vi": "Người yêu thật sự không cố thay đổi bạn, họ chấp nhận bạn như bạn là.", "vo": ["vi", "en"], "en": "A true lover does not try to change you; they accept you as you are.", "author": "Osho"},
 {"id": "q0362", "vi": "Tình yêu và sợ hãi không thể cùng tồn tại. Khi có tình yêu, sợ hãi biến mất.", "vo": ["vi", "en"], "en": "Love and fear cannot exist together. When love is there, fear disappears.", "author": "Osho"},
 {"id": "q0363", "vi": "Người biết yêu nhìn người khác như một mục đích tự thân, không phải như phương tiện.", "vo": ["vi", "en"], "en": "The one who loves sees the other as an end in themselves, not as a means.", "author": "Osho"},
 {"id": "q0364", "vi": "Tình yêu thật sự luôn tươi mới, nó không bao giờ trở thành thói quen.", "vo": ["vi", "en"], "en": "True love is always fresh, it never becomes a habit.", "author": "Osho"},
 {"id": "q0365", "vi": "Khi bạn yêu, bạn không còn là trung tâm, bạn tan hòa vào người khác.", "vo": ["vi", "en"], "en": "When you love, you are no longer the center; you dissolve into the other.", "author": "Osho"},
 {"id": "q0366", "vi": "Tình yêu không phải là cảm xúc, nó là bản chất của sự hiện hữu.", "vo": ["vi", "en"], "en": "Love is not an emotion, it is the essence of existence.", "author": "Osho"},
 {"id": "q0367", "vi": "Tình yêu thực sự không cần sự chắc chắn; nó sống trong bí ẩn.", "vo": ["vi", "en"], "en": "Real love does not need certainty; it lives in mystery.", "author": "Osho"},
 {"id": "q0368", "vi": "Nếu mọi người bắt đầu trao tình yêu thay vì chỉ nói về nó, trái đất này sẽ trở thành thiên đường.", "vo": ["vi", "en"], "en": "If everyone starts giving love instead of talking about it, this very earth will become a paradise.", "author": "Osho"},
 {"id": "q0369", "vi": "Tình yêu là chiếc gương, trong đó bạn nhìn thấy bản thân mình.", "vo": ["vi", "en"], "en": "Love is a mirror in which you see yourself.", "author": "Osho"},
 {"id": "q0370", "vi": "Người biết yêu không bao giờ nghèo; tình yêu làm mọi người trở nên giàu có.", "vo": ["vi", "en"], "en": "Love makes everybody rich; the one who loves is never poor.", "author": "Osho"},
 {"id": "q0371", "vi": "Tình yêu không phải là lời hứa cho ngày mai, nó là sự hiện diện hôm nay.", "vo": ["vi", "en"], "en": "Love is not a promise for tomorrow, it is a presence today.", "author": "Osho"},
 {"id": "q0372", "vi": "Trong tình yêu, không có chỗ cho cái tôi.", "vo": ["vi", "en"], "en": "In love, there is no place for the ego.", "author": "Osho"},
 {"id": "q0373", "vi": "Người càng yêu, càng dễ tha thứ.", "vo": ["vi", "en"], "en": "The one who loves easily forgives.", "author": "Osho"},
 {"id": "q0374", "vi": "Tình yêu là sự tự do lớn nhất; không gì có thể trói buộc nó.", "vo": ["vi", "en"], "en": "Love is the greatest freedom; nothing can bind it.", "author": "Osho"},
 {"id": "q0375", "vi": "Tình yêu thực sự là khi bạn hạnh phúc chỉ vì người kia hiện hữu.", "vo": ["vi", "en"], "en": "True love is when you are happy just because the other exists.", "author": "Osho"},
 {"id": "q0376", "vi": "Khi tình yêu đến, nó mang theo ánh sáng, niềm vui và hương thơm của sự sống.", "vo": ["vi", "en"], "en": "When love comes, it brings light, joy, and the fragrance of life.", "author": "Osho"},
 {"id": "q0377", "vi": "Tình yêu không biết đến tính toán; nó chỉ biết cho đi.", "vo": ["vi", "en"], "en": "Love knows nothing of calculation; it only knows giving.", "author": "Osho"},
 {"id": "q0378", "vi": "Người yêu thật sự không so sánh, bởi vì với họ, người kia là duy nhất.", "vo": ["vi", "en"], "en": "The true lover never compares, because for him the other is unique.", "author": "Osho"},
 {"id": "q0379", "vi": "Tình yêu không thể bị kiểm soát; càng kiểm soát nó càng chết.", "vo": ["vi", "en"], "en": "Love cannot be controlled; the more you control it, the more it dies.", "author": "Osho"},
 {"id": "q0380", "vi": "Người yêu thực sự nhìn thấy cả vũ trụ trong đôi mắt người kia.", "vo": ["vi", "en"], "en": "The true lover sees the whole universe in the eyes of the other.", "author": "Osho"},
 {"id": "q0381", "vi": "Tình yêu là điệu nhảy của hai linh hồn hòa làm một.", "vo": ["vi", "en"], "en": "Love is the dance of two souls becoming one.", "author": "Osho"},
 {"id": "q0382", "vi": "Tình yêu không thể học qua sách; nó chỉ có thể học bằng cách yêu.", "vo": ["vi", "en"], "en": "Love cannot be learned from books; it can only be learned by loving.", "author": "Osho"},
 {"id": "q0383", "vi": "Người biết yêu không bao giờ thấy người khác là gánh nặng, mà là món quà.", "vo": ["vi", "en"], "en": "The one who loves never sees the other as a burden, but as a gift.", "author": "Osho"},
 {"id": "q0384", "vi": "Tình yêu là cội nguồn của mọi sáng tạo.", "vo": ["vi", "en"], "en": "Love is the source of all creativity.", "author": "Osho"},
 {"id": "q0385", "vi": "Người yêu thật sự không hỏi 'tôi được gì?', mà hỏi 'tôi có thể cho gì?'", "vo": ["vi", "en"], "en": "The true lover does not ask 'what do I get?', but 'what can I give?'", "author": "Osho"},
 {"id": "q0386", "vi": "Tình yêu biến đổi nỗi đau thành trưởng thành.", "vo": ["vi", "en"], "en": "Love transforms pain into maturity.", "author": "Osho"},
 {"id": "q0387", "vi": "Trong tình yêu, im lặng cũng là ngôn ngữ.", "vo": ["vi", "en"], "en": "In love, silence is also a language.", "author": "Osho"},
 {"id": "q0388", "vi": "Tình yêu không bao giờ tìm kiếm sự hoàn hảo; nó yêu cái không hoàn hảo.", "vo": ["vi", "en"], "en": "Love never seeks perfection; it loves the imperfect.", "author": "Osho"},
 {"id": "q0389", "vi": "Khi bạn yêu, bạn mở ra cánh cửa tới vô hạn.", "vo": ["vi", "en"], "en": "When you love, you open the door to infinity.", "author": "Osho"},
 {"id": "q0390", "vi": "Tình yêu là sức mạnh duy nhất có thể biến kẻ thù thành bạn.", "vo": ["vi", "en"], "en": "Love is the only power that can turn an enemy into a friend.", "author": "Osho"},
 {"id": "q0391", "vi": "Người yêu thực sự không bao giờ cảm thấy đủ, vì tình yêu luôn mới.", "vo": ["vi", "en"], "en": "The true lover never feels enough, because love is always new.", "author": "Osho"},
 {"id": "q0392", "vi": "Tình yêu thật sự là một cuộc phiêu lưu không có bản đồ.", "vo": ["vi", "en"], "en": "True love is an adventure without a map.", "author": "Osho"},
 {"id": "q0393", "vi": "Trong tình yêu, không có người thắng hay kẻ thua, chỉ có sự hòa hợp.", "vo": ["vi", "en"], "en": "In love, there is no winner or loser, only harmony.", "author": "Osho"},
 {"id": "q0394", "vi": "Người yêu thật sự thấy sự hiện diện của Thượng đế trong người kia.", "vo": ["vi", "en"], "en": "The true lover sees the presence of God in the other.", "author": "Osho"},
 {"id": "q0395", "vi": "Tình yêu là lời cầu nguyện cao nhất.", "vo": ["vi", "en"], "en": "Love is the highest prayer.", "author": "Osho"},
 {"id": "q0396", "vi": "Người biết yêu không bao giờ khép cửa trái tim.", "vo": ["vi", "en"], "en": "The one who loves never closes the door of the heart.", "author": "Osho"},
 {"id": "q0397", "vi": "Tình yêu thực sự là ánh sáng dẫn bạn qua bóng tối.", "vo": ["vi", "en"], "en": "True love is the light that guides you through the darkness.", "author": "Osho"},
 {"id": "q0398", "vi": "Can đảm là sống liều lĩnh với niềm vui, chứ không phải với nỗi sợ.", "vo": ["vi", "en"], "en": "Courage is living dangerously with joy, not with fear.", "author": "Osho"},
 {"id": "q0399", "vi": "Người dũng cảm không chờ đợi sự chắc chắn, họ bước đi trong cái không biết.", "vo": ["vi", "en"], "en": "The courageous person does not wait for certainty, he steps into the unknown.", "author": "Osho"},
 {"id": "q0400", "vi": "Sáng tạo chỉ đến khi bạn yêu cuộc sống đủ để muốn làm nó đẹp hơn.", "vo": ["vi", "en"], "en": "Creativity comes only when you love life enough to want to enhance its beauty.", "author": "Osho"},
 {"id": "q0401", "vi": "Tự do không phải là làm bất cứ điều gì bạn muốn, mà là khả năng sống đúng với bản chất của mình.", "vo": ["vi", "en"], "en": "Freedom is not about doing what you want, but about being able to live your true nature.", "author": "Osho"},
 {"id": "q0402", "vi": "Người sáng tạo là người yêu cuộc sống đến mức không thể không sáng tạo.", "vo": ["vi", "en"], "en": "The creative person is one who loves life so much that he cannot help but create.", "author": "Osho"},
 {"id": "q0403", "vi": "Tự do là dám là chính mình, bất chấp mọi kỳ vọng.", "vo": ["vi", "en"], "en": "Freedom is the courage to be yourself, in spite of all expectations.", "author": "Osho"},
 {"id": "q0404", "vi": "Người dũng cảm biến mọi trở ngại thành cơ hội.", "vo": ["vi", "en"], "en": "The courageous person turns every obstacle into an opportunity.", "author": "Osho"},
 {"id": "q0405", "vi": "Sáng tạo là lời cầu nguyện cao nhất của sự sống.", "vo": ["vi", "en"], "en": "Creativity is the highest prayer of life.", "author": "Osho"},
 {"id": "q0406", "vi": "Tự do thật sự không ai có thể cho bạn, nó chỉ đến từ bên trong.", "vo": ["vi", "en"], "en": "True freedom cannot be given to you by anyone; it comes only from within.", "author": "Osho"},
 {"id": "q0407", "vi": "Người dũng cảm biết rằng cái chết là chắc chắn, vì thế họ sống trọn vẹn.", "vo": ["vi", "en"], "en": "The courageous person knows death is certain, so he lives totally.", "author": "Osho"},
 {"id": "q0408", "vi": "Sáng tạo là sống trong hiện tại, không lặp lại quá khứ.", "vo": ["vi", "en"], "en": "Creativity is living in the present, not repeating the past.", "author": "Osho"},
 {"id": "q0409", "vi": "Tự do không phải là nổi loạn chống lại người khác, mà là vượt lên chính mình.", "vo": ["vi", "en"], "en": "Freedom is not rebellion against others, it is rising above yourself.", "author": "Osho"},
 {"id": "q0410", "vi": "Người dũng cảm không chờ đợi an toàn, họ nhảy vào cái không biết với niềm tin.", "vo": ["vi", "en"], "en": "The courageous do not wait for safety, they jump into the unknown with trust.", "author": "Osho"},
 {"id": "q0411", "vi": "Sáng tạo là biểu hiện tự nhiên của tâm hồn tự do.", "vo": ["vi", "en"], "en": "Creativity is the natural expression of a free soul.", "author": "Osho"},
 {"id": "q0412", "vi": "Người quan sát hơi thở sẽ thấy được bản chất của sự sống.", "vo": ["vi", "en"], "en": "One who watches the breath will see the nature of life.", "author": "Osho"},
 {"id": "q0413", "vi": "Khi tâm trí im lặng, bạn nghe được tiếng nói của linh hồn.", "vo": ["vi", "en"], "en": "When the mind is silent, you can hear the voice of the soul.", "author": "Osho"},
 {"id": "q0414", "vi": "Thiền không phải là tập trung, mà là mở rộng ý thức.", "vo": ["vi", "en"], "en": "Meditation is not concentration, it is the expansion of consciousness.", "author": "Osho"},
 {"id": "q0415", "vi": "Hơi thở là cầu nối giữa thân và tâm.", "vo": ["vi", "en"], "en": "Breath is the bridge between body and mind.", "author": "Osho"},
 {"id": "q0416", "vi": "Khi bạn quan sát, bạn tách mình khỏi tâm trí và trở thành nhân chứng.", "vo": ["vi", "en"], "en": "When you observe, you separate yourself from the mind and become a witness.", "author": "Osho"},
 {"id": "q0417", "vi": "Sự tỉnh thức làm tan biến bóng tối vô minh.", "vo": ["vi", "en"], "en": "Awareness dissolves the darkness of ignorance.", "author": "Osho"},
 {"id": "q0418", "vi": "Thiền không thêm gì vào bạn, nó lấy đi cái giả tạo.", "vo": ["vi", "en"], "en": "Meditation does not add anything to you, it only removes the false.", "author": "Osho"},
 {"id": "q0419", "vi": "Trong im lặng, bạn tìm thấy sự thật.", "vo": ["vi", "en"], "en": "In silence, you find truth.", "author": "Osho"},
 {"id": "q0420", "vi": "Quan sát suy nghĩ giống như quan sát những đám mây trôi qua bầu trời.", "vo": ["vi", "en"], "en": "Watching thoughts is like watching clouds pass across the sky.", "author": "Osho"},
 {"id": "q0421", "vi": "Tỉnh thức biến đời sống thường ngày thành thiền.", "vo": ["vi", "en"], "en": "Awareness turns everyday life into meditation.", "author": "Osho"},
 {"id": "q0422", "vi": "Khoảnh khắc bạn hiện diện toàn vẹn, bạn là thiền.", "vo": ["vi", "en"], "en": "The moment you are totally present, you are meditation.", "author": "Osho"},
 {"id": "q0423", "vi": "Thiền không phải là hành động, mà là trạng thái tồn tại.", "vo": ["vi", "en"], "en": "Meditation is not an act, it is a state of being.", "author": "Osho"},
 {"id": "q0424", "vi": "Người sống trong tỉnh thức biến mọi chuyển động thành điệu nhạc.", "vo": ["vi", "en"], "en": "The one who lives in awareness turns every movement into music.", "author": "Osho"},
 {"id": "q0425", "vi": "Ý thức giống như ngọn lửa thiêu rụi bóng tối.", "vo": ["vi", "en"], "en": "Consciousness is like a flame that burns away darkness.", "author": "Osho"},
 {"id": "q0426", "vi": "Thiền giúp bạn trở nên trống rỗng để cuộc sống tuôn chảy qua bạn.", "vo": ["vi", "en"], "en": "Meditation helps you become empty so that life can flow through you.", "author": "Osho"},
 {"id": "q0427", "vi": "Tỉnh thức là sự giàu có duy nhất không thể mất đi.", "vo": ["vi", "en"], "en": "Awareness is the only wealth that cannot be lost.", "author": "Osho"},
 {"id": "q0428", "vi": "Thiền là không gian giữa hai suy nghĩ.", "vo": ["vi", "en"], "en": "Meditation is the space between two thoughts.", "author": "Osho"},
 {"id": "q0429", "vi": "Khi bạn nhận biết, ngay cả hơi thở bình thường cũng trở nên thiêng liêng.", "vo": ["vi", "en"], "en": "When you are aware, even ordinary breathing becomes sacred.", "author": "Osho"},
 {"id": "q0430", "vi": "Im lặng bên trong là bản nhạc nền của sự sống.", "vo": ["vi", "en"], "en": "Inner silence is the background music of life.", "author": "Osho"},
 {"id": "q0431", "vi": "Thiền là sự thức tỉnh khỏi giấc mơ của tâm trí.", "vo": ["vi", "en"], "en": "Meditation is awakening from the dream of the mind.", "author": "Osho"},
 {"id": "q0432", "vi": "Tỉnh thức là nghệ thuật sống trong hiện tại.", "vo": ["vi", "en"], "en": "Awareness is the art of living in the present.", "author": "Osho"},
 {"id": "q0433", "vi": "Người biết thiền không bị lay động bởi sóng gió cuộc đời.", "vo": ["vi", "en"], "en": "The meditative person is not shaken by the storms of life.", "author": "Osho"},
 {"id": "q0434", "vi": "Thiền là cách để tiếp xúc với chính bản thể của bạn.", "vo": ["vi", "en"], "en": "Meditation is the way to contact your own being.", "author": "Osho"},
 {"id": "q0435", "vi": "Trong tỉnh thức, bạn thấy mình không phải là tâm trí.", "vo": ["vi", "en"], "en": "In awareness, you realize you are not the mind.", "author": "Osho"},
 {"id": "q0436", "vi": "Sự yên tĩnh bên trong là cánh cửa mở ra vĩnh hằng.", "vo": ["vi", "en"], "en": "Inner stillness is the door to eternity.", "author": "Osho"},
 {"id": "q0437", "vi": "Thiền không tìm kiếm câu trả lời, mà phá hủy câu hỏi.", "vo": ["vi", "en"], "en": "Meditation does not seek answers, it destroys the questions.", "author": "Osho"},
 {"id": "q0438", "vi": "Người tỉnh thức không sống trong ký ức, cũng không sống trong ảo tưởng.", "vo": ["vi", "en"], "en": "The aware one lives neither in memory nor in illusion.", "author": "Osho"},
 {"id": "q0439", "vi": "Thiền là sự quay về với nguồn gốc bên trong.", "vo": ["vi", "en"], "en": "Meditation is returning to the inner source.", "author": "Osho"},
 {"id": "q0440", "vi": "Tỉnh thức là chìa khóa mở mọi cánh cửa của tâm linh.", "vo": ["vi", "en"], "en": "Awareness is the key that opens all the doors of the spirit.", "author": "Osho"},
 {"id": "q0441", "vi": "Thiền làm tan biến cái tôi.", "vo": ["vi", "en"], "en": "Meditation dissolves the ego.", "author": "Osho"},
 {"id": "q0442", "vi": "Khi bạn hoàn toàn nhận biết, không có sợ hãi.", "vo": ["vi", "en"], "en": "When you are totally aware, there is no fear.", "author": "Osho"},
 {"id": "q0443", "vi": "Thiền là cách duy nhất để biết bạn là ai.", "vo": ["vi", "en"], "en": "Meditation is the only way to know who you are.", "author": "Osho"},
 {"id": "q0444", "vi": "Người tỉnh thức sống như đứa trẻ – hồn nhiên và trọn vẹn.", "vo": ["vi", "en"], "en": "The aware one lives like a child – innocent and whole.", "author": "Osho"},
 {"id": "q0445", "vi": "Trong thiền, bạn thấy sự sống là phép màu.", "vo": ["vi", "en"], "en": "In meditation, you see life as a miracle.", "author": "Osho"},
 {"id": "q0446", "vi": "Người dũng cảm không cần bảo đảm, chính sự không chắc chắn mới làm cho cuộc sống đẹp.", "vo": ["vi", "en"], "en": "The courageous person does not need guarantees; uncertainty makes life beautiful.", "author": "Osho"},
 {"id": "q0447", "vi": "Mỗi khoảnh khắc bạn chọn tình yêu thay vì sợ hãi, bạn chọn sự sống.", "vo": ["vi", "en"], "en": "Each moment you choose love over fear, you choose life.", "author": "Osho"},
 {"id": "q0448", "vi": "Sáng tạo là sống với trái tim trẻ thơ.", "vo": ["vi", "en"], "en": "Creativity is living with a childlike heart.", "author": "Osho"},
 {"id": "q0449", "vi": "Tự do không đến từ nổi loạn bên ngoài, mà từ sự tỉnh thức bên trong.", "vo": ["vi", "en"], "en": "Freedom does not come from outer rebellion but from inner awakening.", "author": "Osho"},
 {"id": "q0450", "vi": "Người dũng cảm không bao giờ là kẻ không biết sợ; họ biết sợ nhưng vẫn bước đi.", "vo": ["vi", "en"], "en": "The courageous one is not without fear; he knows fear but still moves forward.", "author": "Osho"},
 {"id": "q0451", "vi": "Tình yêu là ngọn lửa làm tan băng giá của trái tim.", "vo": ["vi", "en"], "en": "Love is the flame that melts the ice of the heart.", "author": "Osho"},
 {"id": "q0452", "vi": "Sáng tạo là cầu nối giữa cái hữu hạn và cái vô hạn.", "vo": ["vi", "en"], "en": "Creativity is the bridge between the finite and the infinite.", "author": "Osho"},
 {"id": "q0453", "vi": "Người tự do không tìm kiếm sự chấp thuận; người ấy sống theo bản chất của mình.", "vo": ["vi", "en"], "en": "The free person does not seek approval; he lives according to his nature.", "author": "Osho"},
 {"id": "q0454", "vi": "Can đảm là nói 'có' với sự sống.", "vo": ["vi", "en"], "en": "Courage is saying 'yes' to life.", "author": "Osho"},
 {"id": "q0455", "vi": "Tình yêu biến đổi những vết thương thành hoa hồng.", "vo": ["vi", "en"], "en": "Love transforms wounds into roses.", "author": "Osho"},
 {"id": "q0456", "vi": "Sáng tạo không bao giờ bắt chước; nó luôn độc đáo.", "vo": ["vi", "en"], "en": "Creativity never imitates; it is always unique.", "author": "Osho"},
 {"id": "q0457", "vi": "Tự do là bầu không khí của linh hồn.", "vo": ["vi", "en"], "en": "Freedom is the very air of the soul.", "author": "Osho"},
 {"id": "q0458", "vi": "Người dũng cảm sống từng ngày như một món quà.", "vo": ["vi", "en"], "en": "The courageous one lives each day as a gift.", "author": "Osho"},
 {"id": "q0459", "vi": "Tình yêu không biết tới biên giới, nó vượt lên trên mọi rào cản.", "vo": ["vi", "en"], "en": "Love knows no boundaries; it transcends all barriers.", "author": "Osho"},
 {"id": "q0460", "vi": "Sáng tạo là tiếng hát của linh hồn tự do.", "vo": ["vi", "en"], "en": "Creativity is the song of a free soul.", "author": "Osho"},
 {"id": "q0461", "vi": "Can đảm không phải là không biết sợ; mà là đi xuyên qua nỗi sợ.", "vo": ["vi", "en"], "en": "Courage is not the absence of fear; it is the ability to move through fear.", "author": "Osho"},
 {"id": "q0462", "vi": "Người sáng tạo không lặp lại quá khứ, họ tạo ra cái mới.", "vo": ["vi", "en"], "en": "The creative person does not repeat the past; he creates the new.", "author": "Osho"},
 {"id": "q0463", "vi": "Tự do là khả năng sống đúng với bản chất của mình, không bị áp đặt.", "vo": ["vi", "en"], "en": "Freedom is the ability to live according to your own nature, without imposition.", "author": "Osho"},
 {"id": "q0464", "vi": "Người dũng cảm sống trong cái không biết.", "vo": ["vi", "en"], "en": "The courageous person lives in the unknown.", "author": "Osho"},
 {"id": "q0465", "vi": "Sáng tạo là tình yêu thể hiện trong hành động.", "vo": ["vi", "en"], "en": "Creativity is love expressing itself in action.", "author": "Osho"},
 {"id": "q0466", "vi": "Tự do không thể được ban cho; nó phải được giành lấy từ bên trong.", "vo": ["vi", "en"], "en": "Freedom cannot be given; it must be claimed from within.", "author": "Osho"},
 {"id": "q0467", "vi": "Can đảm là hạt giống của mọi biến đổi.", "vo": ["vi", "en"], "en": "Courage is the seed of all transformation.", "author": "Osho"},
 {"id": "q0468", "vi": "Người sáng tạo là người không thể sống mà không sáng tạo.", "vo": ["vi", "en"], "en": "The creative person is one who cannot live without creating.", "author": "Osho"},
 {"id": "q0469", "vi": "Tự do là nền tảng của mọi niềm vui.", "vo": ["vi", "en"], "en": "Freedom is the foundation of all joy.", "author": "Osho"},
 {"id": "q0470", "vi": "Người dũng cảm nói 'có' với sự sống, bất kể điều gì đến.", "vo": ["vi", "en"], "en": "The courageous says 'yes' to life, whatever comes.", "author": "Osho"},
 {"id": "q0471", "vi": "Sáng tạo là tiếng hát của sự sống.", "vo": ["vi", "en"], "en": "Creativity is the song of life.", "author": "Osho"},
 {"id": "q0472", "vi": "Người tự do không bị giam cầm trong ý kiến của người khác.", "vo": ["vi", "en"], "en": "The free person is not imprisoned by the opinions of others.", "author": "Osho"},
 {"id": "q0473", "vi": "Can đảm không phải là một hành động, mà là một phong cách sống.", "vo": ["vi", "en"], "en": "Courage is not an act, it is a style of living.", "author": "Osho"},
 {"id": "q0474", "vi": "Người sáng tạo biến cả thất bại thành cơ hội học hỏi.", "vo": ["vi", "en"], "en": "The creative person turns even failure into an opportunity to learn.", "author": "Osho"},
 {"id": "q0475", "vi": "Tự do là sự trưởng thành của tâm thức.", "vo": ["vi", "en"], "en": "Freedom is the maturity of consciousness.", "author": "Osho"},
 {"id": "q0476", "vi": "Người dũng cảm là người sẵn sàng đánh đổi an toàn lấy sự sống.", "vo": ["vi", "en"], "en": "The courageous one is willing to risk security for life.", "author": "Osho"},
 {"id": "q0477", "vi": "Sáng tạo là cầu nguyện của trái tim.", "vo": ["vi", "en"], "en": "Creativity is the prayer of the heart.", "author": "Osho"},
 {"id": "q0478", "vi": "Tự do là khả năng chọn lựa con đường riêng của mình.", "vo": ["vi", "en"], "en": "Freedom is the ability to choose your own path.", "author": "Osho"},
 {"id": "q0479", "vi": "Can đảm là cánh cửa dẫn đến chân lý.", "vo": ["vi", "en"], "en": "Courage is the door to truth.", "author": "Osho"},
 {"id": "q0480", "vi": "Người sáng tạo không bao giờ nhàm chán, vì cuộc sống luôn mới mẻ.", "vo": ["vi", "en"], "en": "The creative person is never bored, because life is always new.", "author": "Osho"},
 {"id": "q0481", "vi": "Tự do là khả năng sống không hối tiếc.", "vo": ["vi", "en"], "en": "Freedom is the ability to live without regret.", "author": "Osho"},
 {"id": "q0482", "vi": "Can đảm nghĩa là chọn sự phiêu lưu thay vì sự thoải mái.", "vo": ["vi", "en"], "en": "Courage means choosing adventure over comfort.", "author": "Osho"},
 {"id": "q0483", "vi": "Sáng tạo là dấu hiệu của một tâm hồn khỏe mạnh.", "vo": ["vi", "en"], "en": "Creativity is the sign of a healthy soul.", "author": "Osho"},
 {"id": "q0484", "vi": "Người tự do không hỏi đường, họ tự tìm ra con đường.", "vo": ["vi", "en"], "en": "The free person does not ask for the way; he finds his own.", "author": "Osho"},
 {"id": "q0485", "vi": "Người dũng cảm không chờ đợi phép màu, họ tự tạo ra phép màu.", "vo": ["vi", "en"], "en": "The courageous do not wait for miracles; they create them.", "author": "Osho"},
 {"id": "q0486", "vi": "Sáng tạo là hành trình trở về với chính mình.", "vo": ["vi", "en"], "en": "Creativity is the journey back to oneself.", "author": "Osho"},
 {"id": "q0487", "vi": "Tự do là bản nhạc mà chỉ trái tim can đảm mới nghe được.", "vo": ["vi", "en"], "en": "Freedom is the song only the courageous heart can hear.", "author": "Osho"},
 {"id": "q0488", "vi": "Can đảm là nghệ thuật sống không hối tiếc.", "vo": ["vi", "en"], "en": "Courage is the art of living without regret.", "author": "Osho"},
 {"id": "q0489", "vi": "Sáng tạo là con đường của niềm vui.", "vo": ["vi", "en"], "en": "Creativity is the path of joy.", "author": "Osho"},
 {"id": "q0490", "vi": "Tự do là khi bạn không cần phải trở thành ai khác.", "vo": ["vi", "en"], "en": "Freedom is when you don’t need to become someone else.", "author": "Osho"},
 {"id": "q0491", "vi": "Người dũng cảm không trì hoãn sự sống.", "vo": ["vi", "en"], "en": "The courageous do not postpone life.", "author": "Osho"},
 {"id": "q0492", "vi": "Sáng tạo là khi bạn để sự sống chảy qua bạn mà không cản trở.", "vo": ["vi", "en"], "en": "Creativity is when you let life flow through you without obstruction.", "author": "Osho"},
 {"id": "q0493", "vi": "Người tự do biết ơn cả nỗi đau, vì nó cũng là một phần của sự sống.", "vo": ["vi", "en"], "en": "The free person is grateful even for pain, because it too is part of life.", "author": "Osho"},
 {"id": "q0494", "vi": "Can đảm biến mỗi ngày thành một cuộc phiêu lưu.", "vo": ["vi", "en"], "en": "Courage turns each day into an adventure.", "author": "Osho"},
 {"id": "q0495", "vi": "Sáng tạo là dấu hiệu của tình yêu với sự sống.", "vo": ["vi", "en"], "en": "Creativity is the sign of love for life.", "author": "Osho"},
 {"id": "q0496", "vi": "Tự do là khi bạn sống không phụ thuộc vào sự công nhận của người khác.", "vo": ["vi", "en"], "en": "Freedom is when you live without depending on the recognition of others.", "author": "Osho"},
 {"id": "q0497", "vi": "Người dũng cảm chọn con đường ít người đi.", "vo": ["vi", "en"], "en": "The courageous choose the road less traveled.", "author": "Osho"},
 {"id": "q0498", "vi": "Sáng tạo là sự phản chiếu của tinh thần tự do.", "vo": ["vi", "en"], "en": "Creativity is the reflection of a free spirit.", "author": "Osho"},
 {"id": "q0499", "vi": "Tự do là khi bạn sống mà không bị điều kiện hóa.", "vo": ["vi", "en"], "en": "Freedom is when you live without conditioning.", "author": "Osho"},
 {"id": "q0500", "vi": "Can đảm là tình yêu với cái chưa biết.", "vo": ["vi", "en"], "en": "Courage is love for the unknown.", "author": "Osho"},
 {"id": "q0501", "vi": "Sáng tạo là hơi thở của linh hồn.", "vo": ["vi", "en"], "en": "Creativity is the breath of the soul.", "author": "Osho"},
 {"id": "q0502", "vi": "Người tự do không bắt chước, họ sống thật.", "vo": ["vi", "en"], "en": "The free person does not imitate; he lives authentically.", "author": "Osho"},
 {"id": "q0503", "vi": "Người dũng cảm biến cả bóng tối thành bạn đồng hành.", "vo": ["vi", "en"], "en": "The courageous turns even darkness into a companion.", "author": "Osho"},
 {"id": "q0504", "vi": "Sáng tạo là cách để cảm ơn sự sống.", "vo": ["vi", "en"], "en": "Creativity is a way to say thank you to life.", "author": "Osho"},
 {"id": "q0505", "vi": "Tự do là sống trong chân thật, không đeo mặt nạ.", "vo": ["vi", "en"], "en": "Freedom is living in truth, without masks.", "author": "Osho"},
 {"id": "q0506", "vi": "Can đảm là đi vào bóng tối mà không đèn soi.", "vo": ["vi", "en"], "en": "Courage is entering the darkness without a lamp.", "author": "Osho"},
 {"id": "q0507", "vi": "Sáng tạo là hạt giống của niềm vui.", "vo": ["vi", "en"], "en": "Creativity is the seed of joy.", "author": "Osho"},
 {"id": "q0508", "vi": "Người tự do không cần lý do để sống, chính sự sống đã đủ.", "vo": ["vi", "en"], "en": "The free person needs no reason to live; life itself is enough.", "author": "Osho"},
 {"id": "q0509", "vi": "Can đảm không phải là đi tìm sự nguy hiểm, mà là sẵn sàng đón nhận sự sống như nó đến.", "vo": ["vi", "en"], "en": "Courage is not seeking danger, but being ready to embrace life as it comes.", "author": "Osho"},
 {"id": "q0510", "vi": "Người sáng tạo nhìn thấy cái đẹp trong những điều bình thường.", "vo": ["vi", "en"], "en": "The creative person sees beauty in the ordinary.", "author": "Osho"},
 {"id": "q0511", "vi": "Tự do nghĩa là buông bỏ sự đồng nhất với tâm trí.", "vo": ["vi", "en"], "en": "Freedom means dropping identification with the mind.", "author": "Osho"},
 {"id": "q0512", "vi": "Người dũng cảm sống mà không bám víu.", "vo": ["vi", "en"], "en": "The courageous live without clinging.", "author": "Osho"},
 {"id": "q0513", "vi": "Sáng tạo không phải là xa xỉ, nó là nhu cầu của linh hồn.", "vo": ["vi", "en"], "en": "Creativity is not a luxury, it is a necessity of the soul.", "author": "Osho"},
 {"id": "q0514", "vi": "Tự do không phải là chống lại, mà là vượt lên.", "vo": ["vi", "en"], "en": "Freedom is not against, it is beyond.", "author": "Osho"},
 {"id": "q0515", "vi": "Can đảm là dám bước vào tình yêu.", "vo": ["vi", "en"], "en": "Courage is daring to enter into love.", "author": "Osho"},
 {"id": "q0516", "vi": "Sáng tạo là niềm vui chơi đùa với sự sống.", "vo": ["vi", "en"], "en": "Creativity is the joy of playing with life.", "author": "Osho"},
 {"id": "q0517", "vi": "Tự do là khả năng ở một mình và hạnh phúc.", "vo": ["vi", "en"], "en": "Freedom is the ability to be alone and happy.", "author": "Osho"},
 {"id": "q0518", "vi": "Người dũng cảm biết rằng không có gì để mất, bởi vì sự sống là món quà đã cho.", "vo": ["vi", "en"], "en": "The courageous know there is nothing to lose, because life is already given as a gift.", "author": "Osho"},
 {"id": "q0519", "vi": "Sáng tạo là sự nổi loạn chống lại cái tầm thường.", "vo": ["vi", "en"], "en": "Creativity is a rebellion against the mediocre.", "author": "Osho"},
 {"id": "q0520", "vi": "Tự do là sự trưởng thành để sống theo nội tâm, không theo đám đông.", "vo": ["vi", "en"], "en": "Freedom is the maturity to live inwardly, not follow the crowd.", "author": "Osho"},
 {"id": "q0521", "vi": "Can đảm là sức mạnh duy nhất để vượt qua nỗi sợ chết.", "vo": ["vi", "en"], "en": "Courage is the only strength to transcend the fear of death.", "author": "Osho"},
 {"id": "q0522", "vi": "Người sáng tạo không bao giờ cạn ý tưởng, bởi cuộc sống là vô tận.", "vo": ["vi", "en"], "en": "The creative person never runs out of ideas, because life is infinite.", "author": "Osho"},
 {"id": "q0523", "vi": "Tự do là khả năng không cần trở thành ai đó để được yêu thương.", "vo": ["vi", "en"], "en": "Freedom is the ability not to become somebody to be loved.", "author": "Osho"},
 {"id": "q0524", "vi": "Người dũng cảm chọn sống trọn vẹn thay vì sống lâu.", "vo": ["vi", "en"], "en": "The courageous choose to live totally rather than live long.", "author": "Osho"},
 {"id": "q0525", "vi": "Sáng tạo là hành trình không có điểm đến.", "vo": ["vi", "en"], "en": "Creativity is a journey without destination.", "author": "Osho"},
 {"id": "q0526", "vi": "Tự do không phải là mục tiêu, nó là con đường.", "vo": ["vi", "en"], "en": "Freedom is not the goal, it is the path.", "author": "Osho"},
 {"id": "q0527", "vi": "Người dũng cảm không lùi lại khi đối diện với sự thật.", "vo": ["vi", "en"], "en": "The courageous do not step back when facing truth.", "author": "Osho"},
 {"id": "q0528", "vi": "Sáng tạo là sự hòa hợp giữa tâm hồn và vũ trụ.", "vo": ["vi", "en"], "en": "Creativity is the harmony between the soul and the universe.", "author": "Osho"},
 {"id": "q0529", "vi": "Tự do thật sự là khi bạn thôi tìm kiếm sự tự do.", "vo": ["vi", "en"], "en": "True freedom is when you stop seeking freedom.", "author": "Osho"},
 {"id": "q0530", "vi": "Can đảm làm cho sự sống trở nên mãnh liệt.", "vo": ["vi", "en"], "en": "Courage makes life intense.", "author": "Osho"},
 {"id": "q0531", "vi": "Sáng tạo biến hỗn loạn thành nghệ thuật.", "vo": ["vi", "en"], "en": "Creativity turns chaos into art.", "author": "Osho"},
 {"id": "q0532", "vi": "Tự do là khi bạn chấp nhận chính mình hoàn toàn.", "vo": ["vi", "en"], "en": "Freedom is when you accept yourself totally.", "author": "Osho"},
 {"id": "q0533", "vi": "Người dũng cảm là người vẫn bước đi dù con đường mịt mờ.", "vo": ["vi", "en"], "en": "The courageous is the one who keeps walking even when the path is unclear.", "author": "Osho"},
 {"id": "q0534", "vi": "Sáng tạo là cuộc đối thoại với cái chưa biết.", "vo": ["vi", "en"], "en": "Creativity is a dialogue with the unknown.", "author": "Osho"},
 {"id": "q0535", "vi": "Tự do là khả năng mỉm cười trong mọi hoàn cảnh.", "vo": ["vi", "en"], "en": "Freedom is the ability to smile in every situation.", "author": "Osho"},
 {"id": "q0536", "vi": "Can đảm không phải là tìm cái chết, mà là sống không sợ chết.", "vo": ["vi", "en"], "en": "Courage is not seeking death, but living without the fear of death.", "author": "Osho"},
 {"id": "q0537", "vi": "Sáng tạo là niềm vui chơi đùa với năng lượng của vũ trụ.", "vo": ["vi", "en"], "en": "Creativity is the joy of playing with the energies of the universe.", "author": "Osho"},
 {"id": "q0538", "vi": "Tự do là khả năng nói 'không' khi cần thiết.", "vo": ["vi", "en"], "en": "Freedom is the ability to say 'no' when needed.", "author": "Osho"},
 {"id": "q0539", "vi": "Người dũng cảm nhìn thẳng vào nỗi sợ và mỉm cười.", "vo": ["vi", "en"], "en": "The courageous look straight into fear and smile.", "author": "Osho"},
 {"id": "q0540", "vi": "Sáng tạo là khả năng biến giọt nước mắt thành nụ cười.", "vo": ["vi", "en"], "en": "Creativity is the ability to turn tears into smiles.", "author": "Osho"},
 {"id": "q0541", "vi": "Tự do là khi bạn sống không bị quá khứ ám ảnh.", "vo": ["vi", "en"], "en": "Freedom is when you live without being haunted by the past.", "author": "Osho"},
 {"id": "q0542", "vi": "Niềm vui không phải là cái gì đó bạn đạt được, nó là cách bạn sống.", "vo": ["vi", "en"], "en": "Joy is not something you attain, it is the way you live.", "author": "Osho"},
 {"id": "q0543", "vi": "Cuộc sống không phải là bài toán để giải, mà là một bí ẩn để sống.", "vo": ["vi", "en"], "en": "Life is not a problem to be solved, it is a mystery to be lived.", "author": "Osho"},
 {"id": "q0544", "vi": "Cái chết không phải là sự kết thúc, nó là đỉnh cao của cuộc sống.", "vo": ["vi", "en"], "en": "Death is not the end, it is the climax of life.", "author": "Osho"},
 {"id": "q0545", "vi": "Niềm vui thực sự không phụ thuộc vào điều kiện, nó đến từ bên trong.", "vo": ["vi", "en"], "en": "True joy is unconditional; it comes from within.", "author": "Osho"},
 {"id": "q0546", "vi": "Người sống với ý thức biến từng ngày thành lễ hội.", "vo": ["vi", "en"], "en": "The conscious person makes every day a festival.", "author": "Osho"},
 {"id": "q0547", "vi": "Cái chết là cánh cửa dẫn tới sự bất tử.", "vo": ["vi", "en"], "en": "Death is the door to immortality.", "author": "Osho"},
 {"id": "q0548", "vi": "Hãy sống như thể hôm nay là ngày cuối cùng của bạn.", "vo": ["vi", "en"], "en": "Live as if today is your last day.", "author": "Osho"},
 {"id": "q0549", "vi": "Niềm vui không thể được tìm thấy trong vật chất, nó ở trong trạng thái hiện hữu.", "vo": ["vi", "en"], "en": "Joy cannot be found in possessions, it is in your state of being.", "author": "Osho"},
 {"id": "q0550", "vi": "Người biết yêu sự sống cũng biết yêu cái chết.", "vo": ["vi", "en"], "en": "One who loves life also loves death.", "author": "Osho"},
 {"id": "q0551", "vi": "Bình an đến khi bạn buông bỏ sự kiểm soát.", "vo": ["vi", "en"], "en": "Peace comes when you drop control.", "author": "Osho"},
 {"id": "q0552", "vi": "Niềm vui là hương thơm của tâm hồn tỉnh thức.", "vo": ["vi", "en"], "en": "Joy is the fragrance of an awakened soul.", "author": "Osho"},
 {"id": "q0553", "vi": "Cuộc sống không có ý nghĩa ngoài chính nó.", "vo": ["vi", "en"], "en": "Life has no meaning beyond itself.", "author": "Osho"},
 {"id": "q0554", "vi": "Cái chết không phải là kẻ thù, nó là bạn đồng hành của sự sống.", "vo": ["vi", "en"], "en": "Death is not the enemy, it is the companion of life.", "author": "Osho"},
 {"id": "q0555", "vi": "Người vui vẻ là người gần gũi nhất với Thượng đế.", "vo": ["vi", "en"], "en": "The joyful person is the closest to God.", "author": "Osho"},
 {"id": "q0556", "vi": "Hãy cười nhiều hơn, bởi vì tiếng cười cũng là lời cầu nguyện.", "vo": ["vi", "en"], "en": "Laugh more, because laughter too is prayer.", "author": "Osho"},
 {"id": "q0557", "vi": "Người sợ chết không bao giờ thực sự sống.", "vo": ["vi", "en"], "en": "One who fears death never really lives.", "author": "Osho"},
 {"id": "q0558", "vi": "Sự im lặng bên trong là nền tảng của bình an.", "vo": ["vi", "en"], "en": "Inner silence is the foundation of peace.", "author": "Osho"},
 {"id": "q0559", "vi": "Niềm vui không cần lý do; nó chỉ cần sự hiện diện.", "vo": ["vi", "en"], "en": "Joy needs no reason; it only needs presence.", "author": "Osho"},
 {"id": "q0560", "vi": "Cuộc sống đẹp bởi vì nó mong manh.", "vo": ["vi", "en"], "en": "Life is beautiful because it is fragile.", "author": "Osho"},
 {"id": "q0561", "vi": "Người giác ngộ chết đi mỗi ngày, và sống lại mỗi ngày.", "vo": ["vi", "en"], "en": "The enlightened one dies each day, and is born again each day.", "author": "Osho"},
 {"id": "q0562", "vi": "Niềm vui không phải là sự đối lập của đau khổ, nó là cách bạn nhìn đau khổ.", "vo": ["vi", "en"], "en": "Joy is not the opposite of pain; it is the way you look at pain.", "author": "Osho"},
 {"id": "q0563", "vi": "Cái chết là bông hoa cuối cùng của sự sống.", "vo": ["vi", "en"], "en": "Death is the ultimate flowering of life.", "author": "Osho"},
 {"id": "q0564", "vi": "Người hạnh phúc không chờ đợi phép màu, họ là phép màu.", "vo": ["vi", "en"], "en": "The happy person does not wait for miracles; he is the miracle.", "author": "Osho"},
 {"id": "q0565", "vi": "Sống mà không biết niềm vui là chưa sống.", "vo": ["vi", "en"], "en": "To live without knowing joy is not to live at all.", "author": "Osho"},
 {"id": "q0566", "vi": "Cái chết là giấc ngủ vĩ đại của sự tồn tại.", "vo": ["vi", "en"], "en": "Death is the great sleep of existence.", "author": "Osho"},
 {"id": "q0567", "vi": "Người bình an là người hòa điệu với vũ trụ.", "vo": ["vi", "en"], "en": "The peaceful person is in harmony with the universe.", "author": "Osho"},
 {"id": "q0568", "vi": "Niềm vui là sự mở rộng của trái tim.", "vo": ["vi", "en"], "en": "Joy is the expansion of the heart.", "author": "Osho"},
 {"id": "q0569", "vi": "Cuộc sống không phải là chuẩn bị, nó là để sống ngay bây giờ.", "vo": ["vi", "en"], "en": "Life is not preparation, it is to be lived right now.", "author": "Osho"},
 {"id": "q0570", "vi": "Cái chết chỉ là thay đổi hình dạng, không phải kết thúc.", "vo": ["vi", "en"], "en": "Death is only a change of form, not the end.", "author": "Osho"},
 {"id": "q0571", "vi": "Người vui sống từng khoảnh khắc như thể nó là tất cả.", "en": "The joyful lives each moment as if it is all.", "vo": ["en"], "author": "Osho"},
 {"id": "q0572", "vi": "Bình an không thể tìm thấy bên ngoài, nó chỉ có bên trong.", "en": "Peace cannot be found outside; it is only within.", "vo": ["en"], "author": "Osho"},
 {"id": "q0573", "vi": "Niềm vui là cách bạn biết mình đang sống thật.", "en": "Joy is how you know you are truly alive.", "vo": ["en"], "author": "Osho"},
 {"id": "q0574", "vi": "Cuộc sống và cái chết không tách biệt; chúng là hai mặt của cùng một đồng xu.", "en": "Life and death are not separate; they are two sides of the same coin.", "vo": ["en"], "author": "Osho"},
 {"id": "q0575", "vi": "Người tỉnh thức đón nhận cả sống lẫn chết với cùng một nụ cười.", "en": "The awakened one receives both life and death with the same smile.", "vo": ["en"], "author": "Osho"},
 {"id": "q0576", "vi": "Niềm vui là trạng thái tự nhiên của tâm hồn.", "en": "Joy is the natural state of the soul.", "vo": ["en"], "author": "Osho"},
 {"id": "q0577", "vi": "Cái chết không lấy đi gì từ bạn, nó chỉ cởi bỏ cái không cần thiết.", "en": "Death takes nothing from you; it only removes the unnecessary.", "vo": ["en"], "author": "Osho"},
 {"id": "q0578", "vi": "Người hạnh phúc không sợ chết, bởi vì họ đã sống trọn vẹn.", "en": "The happy person does not fear death, because he has lived totally.", "vo": ["en"], "author": "Osho"},
 {"id": "q0579", "vi": "Sống với niềm vui là cách cảm ơn sự tồn tại.", "en": "Living joyfully is the way to thank existence.", "vo": ["en"], "author": "Osho"},
 {"id": "q0580", "vi": "Bình an là khi bạn không còn tranh đấu với chính mình.", "en": "Peace is when you no longer fight with yourself.", "vo": ["en"], "author": "Osho"},
 {"id": "q0581", "vi": "Cuộc sống không phải là đích đến, mà là hành trình.", "en": "Life is not a destination, it is a journey.", "vo": ["en"], "author": "Osho"},
 {"id": "q0582", "vi": "Niềm vui sâu sắc nhất là khi bạn quên mất cái tôi.", "en": "The deepest joy is when you forget the ego.", "vo": ["en"], "author": "Osho"},
 {"id": "q0583", "vi": "Cái chết là bậc thầy lớn nhất dạy bạn yêu cuộc sống.", "en": "Death is the greatest master teaching you to love life.", "vo": ["en"], "author": "Osho"},
 {"id": "q0584", "vi": "Người sống với niềm vui là người gieo hạt bình an quanh mình.", "en": "The one who lives joyfully spreads seeds of peace around.", "vo": ["en"], "author": "Osho"},
 {"id": "q0585", "vi": "Sự sống là bài ca, hãy hát nó. Cái chết là im lặng, hãy chấp nhận nó.", "en": "Life is a song, sing it. Death is silence, accept it.", "vo": ["en"], "author": "Osho"},
 {"id": "q0586", "vi": "Niềm vui là khi bạn không còn tìm kiếm, chỉ hiện hữu.", "en": "Joy is when you no longer seek, only exist.", "vo": ["en"], "author": "Osho"},
 {"id": "q0587", "vi": "Cuộc sống không bao giờ lặp lại, từng khoảnh khắc đều mới.", "en": "Life never repeats; each moment is new.", "vo": ["en"], "author": "Osho"},
 {"id": "q0588", "vi": "Người vui vẻ là người biết ơn từng giây phút.", "en": "The joyful is the one grateful for each moment.", "vo": ["en"], "author": "Osho"},
 {"id": "q0589", "vi": "Bình an là hương thơm của một tâm hồn tự do.", "en": "Peace is the fragrance of a free soul.", "vo": ["en"], "author": "Osho"},
 {"id": "q0590", "vi": "Cái chết không kết thúc hành trình, nó mở ra một cánh cửa mới.", "en": "Death does not end the journey; it opens a new door.", "vo": ["en"], "author": "Osho"},
 {"id": "q0591", "vi": "Sống với niềm vui là sống cùng Thượng đế.", "en": "To live joyfully is to live with God.", "vo": ["en"], "author": "Osho"},
 {"id": "q0592", "vi": "Cuộc sống là phúc lành vĩ đại nhất, hãy trân trọng nó.", "en": "Life is the greatest blessing, cherish it.", "vo": ["en"], "author": "Osho"},
 {"id": "q0593", "vi": "Niềm vui không phải là mục tiêu, nó là con đường.", "en": "Joy is not the goal, it is the path.", "vo": ["en"], "author": "Osho"},
 {"id": "q0594", "vi": "Cái chết là sự trở về với nguồn cội.", "en": "Death is the return to the source.", "vo": ["en"], "author": "Osho"},
 {"id": "q0595", "vi": "Người sống bình an biến cả thế giới thành ngôi nhà của mình.", "en": "The peaceful makes the whole world his home.", "vo": ["en"], "author": "Osho"},
 {"id": "q0596", "vi": "Niềm vui thực sự không ai có thể lấy đi được.", "en": "True joy cannot be taken away by anyone.", "vo": ["en"], "author": "Osho"},
 {"id": "q0597", "vi": "Sống với niềm vui là chết đi trong từng khoảnh khắc để tái sinh trong từng khoảnh khắc.", "en": "To live joyfully is to die each moment and be reborn each moment.", "vo": ["en"], "author": "Osho"},
 {"id": "q0598", "vi": "Bình an là nền tảng để yêu thương nảy nở.", "en": "Peace is the foundation where love blossoms.", "vo": ["en"], "author": "Osho"},
 {"id": "q0599", "vi": "Cuộc sống không cần được lý giải, chỉ cần được sống.", "en": "Life does not need to be explained; it only needs to be lived.", "vo": ["en"], "author": "Osho"},
 {"id": "q0600", "vi": "Niềm vui là bài ca của sự tồn tại.", "en": "Joy is the song of existence.", "vo": ["en"], "author": "Osho"},
 {"id": "q0601", "vi": "Cái chết chỉ là sự thay đổi trang trong cuốn sách của sự sống.", "en": "Death is only turning a page in the book of life.", "vo": ["en"], "author": "Osho"},
 {"id": "q0602", "vi": "Người vui vẻ biến đau khổ thành vũ điệu.", "en": "The joyful turns suffering into dance.", "vo": ["en"], "author": "Osho"},
 {"id": "q0603", "vi": "Bình an là sự tĩnh lặng giữa hai nhịp tim.", "en": "Peace is the silence between two heartbeats.", "vo": ["en"], "author": "Osho"},
 {"id": "q0604", "vi": "Niềm vui là sự biết ơn sâu sắc đối với sự sống.", "en": "Joy is deep gratitude for life.", "vo": ["en"], "author": "Osho"},
 {"id": "q0605", "vi": "Cuộc sống và cái chết đều là phước lành, nếu bạn hiểu chúng.", "en": "Life and death are both blessings, if you understand them.", "vo": ["en"], "author": "Osho"},
 {"id": "q0606", "vi": "Người hạnh phúc chết đi như một bông hoa rụng, đẹp và tự nhiên.", "en": "The happy one dies like a flower falling, beautiful and natural.", "vo": ["en"], "author": "Osho"},
 {"id": "q0607", "vi": "Niềm vui là ánh sáng soi rọi bóng tối bên trong.", "en": "Joy is the light that illuminates the inner darkness.", "vo": ["en"], "author": "Osho"},
 {"id": "q0608", "vi": "Cái chết là sự giải thoát tối hậu.", "en": "Death is the ultimate release.", "vo": ["en"], "author": "Osho"},
 {"id": "q0609", "vi": "Bình an là khi bạn hòa hợp với chính mình.", "en": "Peace is when you are in harmony with yourself.", "vo": ["en"], "author": "Osho"},
 {"id": "q0610", "vi": "Sống trong niềm vui là sống trong cõi trời.", "en": "To live in joy is to live in heaven.", "vo": ["en"], "author": "Osho"},
 {"id": "q0611", "vi": "Cuộc sống là điệu nhảy của cái hữu hạn với cái vô hạn.", "en": "Life is the dance of the finite with the infinite.", "vo": ["en"], "author": "Osho"},
 {"id": "q0612", "vi": "Niềm vui là chiếc cầu nối bạn với Thượng đế.", "en": "Joy is the bridge that connects you with God.", "vo": ["en"], "author": "Osho"},
 {"id": "q0613", "vi": "Cái chết không có gì để sợ, nó chỉ là giấc ngủ lớn.", "en": "Death has nothing to fear, it is only a great sleep.", "vo": ["en"], "author": "Osho"},
 {"id": "q0614", "vi": "Người vui vẻ biến cả nước mắt thành nụ cười.", "en": "The joyful turns even tears into smiles.", "vo": ["en"], "author": "Osho"},
 {"id": "q0615", "vi": "Bình an là hơi thở của linh hồn.", "en": "Peace is the breath of the soul.", "vo": ["en"], "author": "Osho"},
 {"id": "q0616", "vi": "Niềm vui là khi bạn thấy sự sống là món quà.", "en": "Joy is when you see life as a gift.", "vo": ["en"], "author": "Osho"},
 {"id": "q0617", "vi": "Cuộc sống là dòng sông, cái chết là đại dương.", "en": "Life is the river, death is the ocean.", "vo": ["en"], "author": "Osho"},
 {"id": "q0618", "vi": "Người hạnh phúc là người không bao giờ mất kết nối với sự sống.", "en": "The happy one never loses connection with life.", "vo": ["en"], "author": "Osho"},
 {"id": "q0619", "vi": "Khi ta ăn một miếng bánh mì, ta thấy được cả vũ trụ trong đó: mưa, nắng, đất, công lao của nông dân, của người thợ làm bánh.", "en": "When we eat a piece of bread, we see the whole universe in it: the sun, the rain, the soil, the farmer, the baker.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0620", "vi": "Ăn cơm trong im lặng là cơ hội để tiếp xúc sâu sắc với từng miếng ăn, với sự sống và với nhau.", "en": "Eating in silence is an opportunity to deeply touch each bite, life itself, and each other.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0621", "vi": "Khi ăn, chỉ ăn thôi. Đừng để tâm trí chạy theo quá khứ hay tương lai.", "en": "When eating, just eat. Don’t let your mind wander to the past or future.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0622", "vi": "Ăn trong chánh niệm là để nuôi dưỡng thân tâm, chứ không phải để lấp đầy sự lo lắng hay buồn chán.", "en": "Mindful eating is to nourish body and mind, not to cover up worry or sadness.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0623", "vi": "Một bát cơm có mặt cả trời đất: mây, mưa, nắng, và tình thương.", "en": "A bowl of rice contains the sky and the earth: clouds, rain, sunshine, and love.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0624", "vi": "Nhai một miếng cơm cho sâu sắc, bạn có thể thấy sự sống mầu nhiệm trong đó.", "en": "Chewing a bite of rice deeply, you can see the miracle of life in it.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0625", "vi": "Khi uống trà, hãy thật sự uống trà. Hãy hiện diện trọn vẹn với tách trà trong tay bạn.", "en": "When drinking tea, really drink tea. Be fully present with the cup in your hands.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0626", "vi": "Mỗi bữa ăn là một bài thực tập. Ăn với lòng biết ơn, ta tiếp xúc với sự sống quanh ta.", "en": "Each meal is a practice. Eating with gratitude, we touch the life around us.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0627", "vi": "Ăn trong chánh niệm giúp ta thấy rõ ta không thể sống một mình; ta sống nhờ muôn loài.", "en": "Mindful eating helps us realize we cannot live alone; we live thanks to all beings.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0628", "vi": "Thực tập ăn cơm trong im lặng là để cảm nhận sâu sắc rằng mỗi hạt cơm là một phép lạ.", "en": "Practicing silent eating helps us deeply feel that each grain of rice is a miracle.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0629", "vi": "Ngồi chỉ để ngồi. Ngồi không phải để đạt đến đâu cả.", "en": "Sit just to sit. Not to arrive anywhere.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0630", "vi": "Ngồi như một ngọn núi. Vững chãi, thảnh thơi.", "en": "Sit like a mountain. Solid, relaxed.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0631", "vi": "Khi ngồi, hãy ngồi như một người tự do.", "en": "When you sit, sit like a free person.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0632", "vi": "Ngồi yên để trở về với chính mình và để bình an lan tỏa.", "en": "Sitting still to come back to yourself and let peace radiate.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0633", "vi": "Ngồi là dừng lại cuộc chạy đua, và tìm lại sự thảnh thơi.", "en": "Sitting is stopping the running and finding relaxation again.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0634", "vi": "Khi bước đi trên đất, hãy bước như thể bạn đang hôn trái đất bằng bàn chân của mình.", "en": "Walk as if you are kissing the Earth with your feet.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0635", "vi": "Mỗi bước chân trong chánh niệm đưa ta trở về nhà.", "en": "Each mindful step brings us back home.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0636", "vi": "Đi không phải để đến, mà để trở về giây phút hiện tại.", "en": "Walk not to arrive, but to be in the present moment.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0637", "vi": "Đi trong chánh niệm là để tiếp xúc với sự sống sâu sắc.", "en": "Walking mindfully is to deeply touch life.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0638", "vi": "Mỗi bước chân có thể nuôi dưỡng sự bình an và niềm vui.", "en": "Each step can generate peace and joy.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0639", "vi": "Nhìn sâu để thấy được bản chất vô thường, vô ngã, và tương tức của mọi hiện tượng.", "en": "Looking deeply, we see the impermanent, non-self, and interbeing nature of all things.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0640", "vi": "Khi nhìn vào một bông hoa, bạn thấy được cả vũ trụ trong đó.", "en": "Looking into a flower, you can see the entire universe.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0641", "vi": "Cái thấy sâu sắc giúp ta không còn giận hờn và sợ hãi.", "en": "Deep looking helps us release anger and fear.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0642", "vi": "Nhìn sâu vào người khác để thấy được nỗi khổ của họ, và lòng từ bi tự nhiên phát sinh.", "en": "Look deeply into another person to see their suffering, and compassion will arise.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0643", "vi": "Nhìn sâu để thấy ta và cái kia không hai.", "en": "Looking deeply, we see that we and the other are not two.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0644", "vi": "Bạn là tôi và tôi là bạn. Chúng ta liên hệ với nhau như một chiếc lá với cây.", "en": "You are me and I am you. We inter-are like a leaf and the tree.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0645", "vi": "Không có gì có thể hiện hữu một mình. Tất cả đều nương tựa lẫn nhau.", "en": "Nothing can exist alone. Everything inter-is.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0646", "vi": "Hiểu được tính tương tức, ta không còn cô đơn nữa.", "en": "Understanding interbeing, we are no longer lonely.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0647", "vi": "Cái này có thì cái kia có. Cái này không thì cái kia không.", "en": "This is, because that is. This is not, because that is not.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0648", "vi": "Nhìn sâu, ta thấy sự sống không bao giờ mất đi, nó chỉ biến chuyển hình tướng.", "en": "Looking deeply, we see life never disappears; it only changes form.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0649", "vi": "Thở vào, tôi biết tôi đang thở vào. Thở ra, tôi mỉm cười. Thực tập này đơn giản đến mức một em bé năm tuổi cũng có thể làm.", "en": "Breathing in, I know I am breathing in. Breathing out, I smile. This practice is so simple even a five-year-old child can do it.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0650", "vi": "Đi trong chánh niệm chỉ là đặt từng bước chân với sự chú ý. Một em bé có thể làm, và một thiền sư cũng làm như vậy.", "en": "Walking mindfully is simply placing each step with awareness. A child can do it, and so can a Zen master.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0651", "vi": "Ngồi yên và thở là phép thực tập ai cũng làm được. Điều quan trọng là sự hiện diện, không phải tuổi tác hay kiến thức.", "en": "Sitting still and breathing is a practice anyone can do. What matters is presence, not age or knowledge.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0652", "vi": "Nếu bạn không thể giải thích đạo Bụt cho một em bé hiểu, thì bạn chưa thực sự hiểu đạo Bụt.", "en": "If you cannot explain Buddhism to a child, you do not truly understand it.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0653", "vi": "Một em bé có thể cười trong khi thở vào và thở ra. Đó chính là thiền tập.", "en": "A child can smile while breathing in and breathing out. That is already meditation.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0654", "vi": "Thực tập chánh niệm không phải để trở thành ai khác, mà để là chính mình. Một em bé hiểu điều này ngay khi chơi đùa.", "en": "Practicing mindfulness is not to become someone else, but to be yourself. A child understands this while playing.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0655", "vi": "Nụ cười của một em bé có thể dạy chúng ta nhiều hơn hàng ngàn cuốn sách.", "en": "The smile of a child can teach us more than a thousand books.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0656", "vi": "Khi ta nắm tay một em bé và bước đi trong chánh niệm, ta và em bé cùng tiếp xúc với bình an.", "en": "When we hold a child’s hand and walk mindfully, both of us touch peace.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0657", "vi": "Chánh niệm đơn giản như thở và mỉm cười. Một em bé năm tuổi làm được, và một thiền sư cũng làm như vậy suốt đời.", "en": "Mindfulness is as simple as breathing and smiling. A five-year-old can do it, and a Zen master practices it all his life.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0658", "vi": "Thiền không phải là điều gì huyền bí. Nó là thở, đi, ngồi, ăn, như một em bé có thể làm — nhưng với sự tỉnh thức.", "en": "Meditation is not something mysterious. It is breathing, walking, sitting, eating, as a child can do — but with awareness.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0659", "vi": "Khi cơn giận khởi lên, hãy trở về với hơi thở. Hơi thở chánh niệm là sợi dây cứu bạn khỏi bị cuốn trôi.", "en": "When anger arises, return to your breath. Mindful breathing is the lifeline that saves you from being swept away.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0660", "vi": "Cái giận giống như một đứa bé khóc, ta phải ôm ấp nó bằng năng lượng chánh niệm.", "en": "Anger is like a crying baby, we must hold it tenderly with the energy of mindfulness.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0661", "vi": "Nếu bạn nhận diện được cơn giận, bạn sẽ không còn là nạn nhân của nó.", "en": "If you recognize your anger, you are no longer its victim.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0662", "vi": "Tĩnh lặng không phải là không có tiếng động, mà là sự vững chãi trước mọi sóng gió.", "en": "Silence is not the absence of sound, but the solidity amidst the storms.", "vo": ["en"], "author": "Thích Nhất Hạnh"},
 {"id": "q0663", "vi": "Năng lượng của chánh niệm có thể ôm ấp và chuyển hóa năng lượng của giận dữ.", "en": "The energy of mindfulness can embrace and transform the energy of anger.", "vo": ["en"], "author": "Thích Nhất Hạnh"}
];
window.__thienJS = (window.__thienJS || 0) + 1;
